    "experiments": "二神经元和四神经元案例及确定性非均匀网络数值实验支持理论条件；测试不同初始误差时，提出控制器在所测设置中达到阈值的时间最短。图像保护实验在盐椒噪声密度 5×10⁻⁴ 时，平均 PSNR 37.170 dB、平均 UACI 0.042653、正确像素 99.854%。",
    "contribution": "给出适用于非交换双侧系数网络的固定时间同步条件，并展示超复数状态在多光谱图像保护中的用法。图像保护演示不证明抗密码分析能力；噪声鲁棒指标只对应所列扰动密度和该实验方案。\n---\nDOI: 10.1016/j.neunet.2026.109528",
