    "summary": "OpenDAR联合分布感知重加权对比学习与伪标签再平衡，在长尾已知类和无标签新类并存时增强尾类及新类识别。",
    "question": "开放世界半监督学习既要区分已知类和新类，又面对头尾类样本严重不均。单独处理开放集或长尾问题会使模型偏向头部类别，并让尾类、新类的表征和伪标签质量进一步下降。",
    "method": "框架用类别分布感知的重加权因子共同调节对比表征学习和伪标签修正：前者提高尾类及新类的学习权重，增强特征可分性；后者依据估计的类别分布重平衡候选伪标签，并结合长尾补偿阈值筛选高质量样本。推理仍按已知类分类和新类聚类评估。",
    "experiments": "在CIFAR-10-LT、CIFAR-100-LT和ImageNet-100-LT上比较开放世界半监督学习方法，结果为三次不同随机种子运行的均值±标准差。CIFAR-10-LT上，OpenDAR相较最佳竞争方法的新类准确率和整体准确率分别高1.8和2.9个百分点（由表中准确率差值计算，属于百分点差而非相对百分比提升）。CIFAR-100-LT与ImageNet-100-LT上的新类准确率增益分别为0.6和0.3个百分点，整体准确率增益分别为1.2和0.3个百分点。",
    "contribution": "方法把类别分布估计、尾类/新类表征增强与伪标签校正放进同一闭环，针对长尾与开放世界交织的训练情形。实验主要基于按不平衡比例构造的视觉基准，真实开放环境中的分布漂移及类别持续到达仍需额外验证。\n---\nDOI: 10.1016/j.neunet.2026.109539",
