    "summary": "EM-AT 用能量建模区分自然样本与对抗样本，并在推理时最小化能量以改善未见攻击下的鲁棒泛化。",
    "question": "对抗训练对训练时攻击有效，但遇到未见攻击样本时鲁棒性可能下降。论文试图用自然样本低能量、对抗样本高能量的结构改善跨攻击泛化。",
    "method": "提出能量式优化，将自然与对抗样本的能量关系纳入训练；推理阶段通过能量最小化减弱扰动影响。理论部分在泛化界中引入能量差异项，属于解释性上界分析，不是针对任意攻击的认证鲁棒保证。",
    "experiments": "在 CIFAR-10、CIFAR-100、SVHN 上以 ℓ∞ 威胁模型评估；除特别说明外预算 ε=8/255，EM-AT、AT、TRADES 使用相同 WRN-28-10 骨干与训练协议，并测试 AutoAttack、PGD/CW 多步及知晓 EM 流程的自适应攻击。CIFAR-10 标准 AutoAttack 下 EM-AT 鲁棒准确率为77.71%，但作者明确该结果未对推理 EM 算子使用 BPDA/EOT；另在 EM-aware 自适应 PGD/CW 协议中，EM-AT 在所列方法中表现最佳。计算代价也有实测：RTX 3090、训练批量120时，每轮训练523.851秒、峰值显存21,762 MiB；PGD-AT为343.174秒和8,400 MiB。",
    "contribution": "EM-AT 将自然/对抗样本能量差纳入训练，并在推理时用能量最小化修正输入；理论给出含能量差异项的鲁棒泛化上界，属于解释性上界而非认证鲁棒保证。三个数据集及指定威胁模型的实验显示其在多种攻击下具有竞争力，但CIFAR-10的77.71%是标准 AutoAttack 流程结果，不是针对 EM 算子的完整自适应验证；自适应证据来自单独的 EM-aware PGD/CW 测试。额外推理修正伴随更高训练时间和显存开销。\n---\nDOI: 10.1016/j.neunet.2026.109521",
