    "summary": "论文提出面向视频动作识别的类增量开集框架，以皮尔逊距离约束类别表征并在相邻阶段对齐预测关系，在学习新动作、保留旧知识和拒识未知动作之间取得平衡。",
    "question": "既有类增量方法通常假设测试样本均属已知类，开集方法则多假设已知类别集合固定；真实视频流会逐步出现新动作，同时还含训练阶段未见类别。只用已知类训练会使已知与未知表征边界模糊，阶段更新又会遗忘旧类的分类和拒识能力。",
    "method": "模型以时序移位模块提取视频时空特征，并用余弦分类器输出类别概率。判别增强模块约束类别原型与其质心的皮尔逊距离，促使已知类表征紧凑、类间更可分；阶段间的logit对齐则分别传递批内样本关系和类别预测关系。两项正则仅在训练期使用，推理仍是原识别器。未知分数取已知类最大概率的补数。",
    "experiments": "在UCF101、HMDB51和Something-Something V2上测试两、五、十阶段协议，未知类不参与训练。五阶段设置以UCF101为已知类、HMDB51为未知类时，准确率为73.26%、AUROC为82.40%、AUPR为64.52%；以SSTH V2为未知集的消融表中，UCF101五阶段的三项指标分别为73.26%、87.09%、73.28%。作者报告整体优于同协议基线。",
    "contribution": "工作明确提出视频类增量开集识别任务，并将类内紧凑约束与跨阶段关系蒸馏结合，避免为拒识另加推理网络。局限是训练没有未知样本，拒识仍依赖已知表征可分性和测试阈值；评估主要依赖有限数据集组合，跨更大规模、细粒度视频集的泛化仍待验证。\n---\nDOI: 10.1016/j.neunet.2026.109529",
    "sample": false,
