    "link": "https://doi.org/10.1016/j.neunet.2026.109533",
    "direction": "人工智能",
    "summary": "ILBD从任务数据自身的分类logit估计类别偏置，并在推理时校正输出，同时自适应筛选伪标签，以应对无标注类别比例未知或与标注集不匹配的长尾半监督学习。",
    "question": "类别不平衡的半监督学习容易让模型偏向头部类别，随后产生的伪标签又强化这种确认偏差。已有logit校正通常依赖已知类别先验或假设无标注集与标注集分布一致，现实中这两点往往无法保证。",
    "method": "ILBD把模型偏置分解为无标签内在偏置与标签引导学习偏置：前者由屏蔽目标类别最大logit后其余类别响应的统计量估计，后者利用任务标注信息刻画学习偏向。双分支训练用于解耦表征学习与偏置估计；推理阶段从logit中减去估计偏置，并按类别自适应阈值筛选伪标签。",
    "experiments": "在CIFAR-10-LT、CIFAR-100-LT、STL-10-LT及自然长尾Small-ImageNet-127上，与半监督及长尾校正基线比较；覆盖无标注比例已知、未知和分布失配情形。指标包括平衡准确率与几何均值，报告值为3个随机种子的均值及标准差。论文报告ILBD在这些设定下稳定改善偏置校正，尤其在无标注分布未知时不需外部先验仍能提升尾类表现。",
    "contribution": "方法不以真实类别先验或外部代理数据作为偏置估计前提，并把后处理logit校准与伪标签过滤结合。证据主要来自人工构造的长尾基准及Small-ImageNet-127；对其他数据分布、标签噪声机制和部署时校准稳定性的适用性仍需进一步验证。\n---\nDOI: 10.1016/j.neunet.2026.109533",
    "sample": false,
