    "question": "既有生物特征联邦学习多处理单一模态，且较少覆盖纵向多模态数据分散在不同终端的现实情形；多终端协作还面临拜占庭和投毒风险。",
    "method": "Multi-FedLinks 由多个具拜占庭鲁棒性的 FedLink 结构组成，同模态客户端先在各自链接内协作，再由第三方服务器连接不同模态链接实现纵向多生物特征训练；论文同时评估标签翻转、模型投毒和数据异质性。",
    "experiments": "在 NUPT-FPV 上评估识别与攻击鲁棒性。表11中该数据集投毒比例20%时，Krum 的 EER/TAR 为1.26%/98.51%，Trim-mean 为1.49%/97.85%，Gaussian 为0.96%/99.05%；表13 FedLink 运行568.76秒，FedAvg 为224.53秒，显示安全机制有计算代价。",
    "contribution": "工作将纵向多模态联邦扩展到生物特征识别，并以 FedLink 链接抵御拜占庭行为。威胁评估并非所有攻击皆被消除：表12分类器后门 ASR 两者均为100%，因此不应把“高安全”解读为全面防护；数据也主要来自单一基准。\n---\nDOI: 10.1016/j.neunet.2026.109519",
