    "summary": "连续吸引子网络仿真显示，适量感觉输入噪声可在部分条件下促进网格样放电形成或改善路径积分，而更强噪声会破坏活动图样并降低位置估计精度。",
    "question": "连续吸引子网络可解释内嗅皮层网格细胞放电和路径积分，但既有模型多使用确定性自运动输入，因而难以判断真实存在的感觉噪声究竟损害还是促进网络计算。",
    "method": "作者在率模型连续吸引子网络中加入随机感觉速度输入，并结合边界细胞输入，测量网格样群体活动的稳定性以及网络位置估计误差。通过改变噪声水平，区分无噪声时已能形成网格场的网络与无噪声下不能形成网格场的网络，检验随机共振现象。",
    "experiments": "仿真发现：原本无噪声即可形成网格场的网络，在多数噪声水平下仍保持图样稳定，最高噪声才出现明显不稳定；原本不能形成网格场的情形，低水平噪声可促成网格样活动，高噪声则抑制形成。对已形成网格场的网络，低噪声可改善位置估计，高噪声使路径积分精度下降。论文还比较不同虚拟轨迹与边界输入。",
    "contribution": "研究展示感觉噪声在连续吸引子网络中可能兼具促进与扰乱作用，并将随机共振关联到网格场形成和路径积分。局限是使用率模型而非脉冲神经元模型，结论来自仿真；不同噪声颜色、乘性噪声及更生理真实机制仍需研究。\n---\nDOI: 10.1016/j.neunet.2026.109546",
