    "summary": "论文从宽网络学习动力学分析稀疏低秩适配SoRA的更新尺度问题，并提出SoRA+用额外缩放因子调节低秩因子学习率，再通过语言理解和摘要任务验证。",
    "question": "SoRA用稀疏门控动态裁剪低秩适配器秩，降低微调与推理开销，但模型宽度增长时不同低秩因子的更新可能失衡，导致学习不足。论文希望明确其尺度条件并修正优化动态。",
    "method": "作者对SoRA的投影矩阵P、对角门控Λ和投影矩阵Q进行宽度尺度分析，指出常见共享学习率配置不一定保证各部分有效更新。SoRA+引入缩放因子μ，在反向传播时放大P与Λ的学习率，并依照门控稀疏性在训练后裁去对应投影分量，保留稀疏适配结构。",
