    "contribution": "工作将稀疏低秩适配的学习率安排与宽网络尺度分析联系起来，提出可直接实施的SoRA+修正。理论结论依赖文中尺度假设；实验覆盖的模型与任务仍有限，且新增前向/梯度计算会影响吞吐，不能把参数高效等同于训练速度必然更快。\n---\nDOI: 10.1016/j.neunet.2026.109543",
