    "contribution": "方法以语言语义作为跨任务监督桥梁，并让不同标签量的数据共享同一表征骨干。研究主要在实验室采集EEG上验证；作者指出极少通道的可穿戴设备需要适配，因此对低通道、噪声更强的真实场景泛化仍不确定。\n---\nDOI: 10.1016/j.neunet.2026.109544",
