    "summary": "SMSL把文本实体、属性和关系组织为语义拓扑，以此引导图文区域对齐并按样本动态校准匹配边界，减少语义近似但关系不一致的误匹配。",
    "question": "图文匹配常用序列级线性表征和固定相似度阈值，面对词面相似但语义关系不同的图文对时，正负样本分数容易重叠。需要显式建模高阶语义结构，并让匹配判定随样本语义复杂度变化。",
    "method": "SMSL包含三个协同模块：TMI依据文本token间实体、属性和关系构造拓扑约束的语义流形；MVG用流形锚点指导视觉区域选择，抑制显著但语义无关的区域；MDT根据拓扑证据与匹配确定性估计样本级动态阈值，取代单一固定间隔。",
    "experiments": "在Flickr30K和MS-COCO进行双向图文检索，以Recall@1/5/10评价，并比较不同文本编码器、视觉骨干和GRU设置。作者报告SMSL在多个设置上取得有竞争力且较稳定的图到文、文到图检索结果；其分析显示流形约束使关键语义token与对应视觉区域的注意更集中。论文强调改善并非所有配置均一致，阈值校准仍有敏感性。",
    "contribution": "贡献在于将结构语义从表征学习延伸到视觉定位和样本级决策边界校准，兼顾细粒度对齐与近重复负例辨别。实验验证范围集中在两个图文检索基准；从所报告实验看，拓扑构建依赖解析质量，对其他语言、复杂关系或真实检索分布的泛化仍需验证。\n---\nDOI: 10.1016/j.neunet.2026.109541",
