    "direction": "人工智能",
    "summary": "GLA-LoRA在低秩微调中加入全局与局部对比对齐及教师蒸馏，分别保持样本间语义结构和样本内特征一致性，以缓解压缩适配造成的知识退化。",
    "question": "LoRA等参数高效微调减少可训练参数，却可能因低秩压缩损失预训练表示和知识。仅关注下游任务标签难以同时维持数据集层面的语义关系及单个样本内部特征结构。",
    "method": "GLA-LoRA以多粒度对比学习执行全局与局部知识对齐：全局目标保留样本间语义结构，局部目标约束单样本特征一致性；教师模型通过知识蒸馏指导低秩适配过程，抑制微调中的表示退化。方法在LoRA适配器上增加辅助训练目标，而非全面更新基础模型。",
    "experiments": "论文在八个基准任务上评估语言理解与生成效果，并比较LoRA等参数高效微调方法；数据集涵盖CoLA、RTE、MRPC、SST-2、QNLI等。作者报告多项任务性能持续改善。效率方面，BERT-Large吞吐为4582.4 tokens/s，相比LoRA的6292.8 tokens/s低27%；Llama2-7B为460.6 tokens/s，相比LoRA低8.6%，体现额外对比目标的计算开销。",
    "contribution": "论文把样本间结构保持、样本内一致性和教师蒸馏合并进参数高效适配流程。性能收益伴随额外计算：作者承认双路径对比目标降低吞吐；因此在资源受限场景需权衡任务质量与训练速度，且基准上的提升不保证每个任务都同幅度获益。\n---\nDOI: 10.1016/j.neunet.2026.109545",
