    "summary": "SubNet在U形盲点重建网络中加入带掩码的空间—光谱自注意力和字典引导的背景分类注意力，以改善复杂高光谱背景建模。",
    "question": "盲点网络可在不依赖异常标签的情况下重建背景，但局部特征难以表达远距离空间—光谱关系，且单一背景模型难以应对多类地物；注意力若读取中心异常像素又会污染重建。论文因此研究如何同时扩大上下文、保留盲点约束并区分背景类别。",
    "method": "SubNet采用带跳连的U-Net编码器—解码器，以掩码卷积和下采样隔离潜在异常。空间—光谱自注意力模块在空间注意力图施加棋盘掩码，避免中心盲点进入特征聚合；潜空间的字典注意力模块用可学习token字典将特征分组，再在组内进行多头自注意力，强化同类背景表征。收敛后以像素级重建误差生成异常图。",
    "experiments": "作者在4个公开高光谱数据集上与8种检测器比较，并进行模块消融、噪声测试及参数分析。SubNet四组AUC(D,F)分别为0.9928、0.9984、0.9954和0.9975，均为表中最高；加入全部模块的完整模型优于单独组件组合。噪声实验中，SubNet在四集的AUC(D,F)为0.9108、0.9884、0.9907、0.9975，高于RX的0.6368、0.9419、0.8909、0.9538。多重注意力也增加了参数和计算开销，高于表中多数深度基线。",
    "contribution": "该方法把保持盲点性质的全局空间—光谱关联建模与多类别背景分组纳入同一重建框架，四个数据集的AUC(D,F)均取得比较方法中的最佳值。作者也明确指出，HSI-I中与异常目标光谱相似的背景材料仍会造成误报；多重注意力增加参数和计算成本，轻量化仍待解决。\n---\nDOI: 10.1016/j.neunet.2026.109548",
