    "summary": "CMAFNet通过双向跨模态交互、层级混合专家和动态关系融合，联合火焰图像、文本描述与工艺数据识别回转窑工况。",
    "question": "氧化锌回转窑的欠烧、适烧和过烧状态关系到能耗、质量与设备安全，传统依赖操作员观察火焰，主观且难以整合图像、文本和过程信号。模态差异、冗余和类别不均衡也使普通融合难以识别细粒度工况。",
    "method": "CMAFNet将火焰图像、由视觉特征及温度规则形成的文本描述、分布式控制系统过程数据统一投影。冻结的CLIP图像与文本编码器提取视觉语言表征；CMIT用六个方向的跨模态注意力交互，EASF分阶段适配与筛选特征，DAF按关系动态融合，层级混合专家处理不同局部模式。复合损失结合跨模态对齐、中心与三元组目标，兼顾类内紧凑和类间区分。",
    "experiments": "在工业窑炉数据的七分类工况识别中，CMAFNet准确率93.65±0.25%、F1为92.16±1.24%、MCC为0.894±0.004；对照最佳基线LMAM的准确率92.61±0.23%、F1为89.94±0.82%。移除对齐损失后准确率降至93.17±0.43%、F1降至91.03±0.78%。另在公开3D打印故障数据集上，准确率86.39±1.08%、F1为86.00±1.07%、MCC为0.791±0.016。",
    "contribution": "研究构建与真实冶炼场景对应的三模态数据及自适应交互架构，报告七类工况的整体指标和公开数据迁移评估，消融也支持对齐与融合模块的作用。工业数据采集与标签源于特定窑炉；从所报告实验看，跨工厂、传感器变化和长期运行漂移尚未得到充分检验，不能仅凭公开3D打印数据外推冶炼现场效果。\n---\nDOI: 10.1016/j.neunet.2026.109552",
