    "method": "框架对无标注图像构造放大与缩小视图。输出空间的SEC-Fuse依据预测不确定性和视图分歧，将像素划为语义核心、边界带和补全区域，再自适应融合两视图概率生成伪标签；特征空间的CSP-Align用非边界高置信区域构建类别原型，约束跨视图类别语义一致。",
