    "contribution": "方法在概率输出和特征表征两个尺度分别处理伪标签噪声与语义漂移，且在多个视觉任务上测试。模型包含区域划分、原型对齐及训练权重等设计；跨域适配和超参数敏感性仍是实用部署时需要关注的问题，当前证据来自公开基准。\n---\nDOI: 10.1016/j.neunet.2026.109547",
