    "summary": "DHGNN-MVC结合关系语义传播、时间注意力与局部—全局及社区演化对比目标，学习动态异构图表示并预测链接。",
    "question": "动态异构图同时包含多类节点关系和时间演化。已有元路径方法较少利用路径中间节点属性，单一未来链接重构目标又容易偏向低阶局部关系，使表示无法反映全局演变。研究要解决如何在不丢失类型语义的前提下整合关系、时间和社区层次信号。",
    "method": "模型分为动态图嵌入学习和多视图联合优化两部分：按关系类型聚合邻居，并结合元路径实例强度构造语义敏感传播；用PPR消息传播扩展信息范围，同时保留节点初始特征；再加入时间位置编码与时间注意力。训练目标联合未来图重构、局部—全局互信息最大化和相邻快照社区中心的演化对比学习，社区目标设有预热阶段。",
    "experiments": "在Aminer（16个快照）、DBLP（10个）和Yelp（12个）上评估链接检测、链接预测及新链接预测，与静态/动态图、同构/异构图基线比较。链接预测表中AUC/AP分别为Aminer 87.92%/86.35%、DBLP 83.37%/82.55%、Yelp 78.60%/77.18%，均高于ACSL的85.26%/83.17%、81.45%/80.26%、75.31%/73.94%。消融移除关系视角、局部—全局或社区演化目标后性能下降；Aminer元路径长度1到6时模型AUC由86.83%降至85.48%，变化较缓。",
    "contribution": "工作把元路径中间节点关系属性显式纳入传播，并以多层次对比目标约束动态表示，三个数据集的链接任务均较强。实验覆盖三种领域图和多个基线，但社区数依赖聚类、超参数及快照划分；从所报告实验看，证据主要来自三个数据集的离线预测，跨领域部署和更长期演化仍未验证。\n---\nDOI: 10.1016/j.neunet.2026.109549",
