    "question": "深度超分辨率需从低分辨率深度恢复几何细节，并借助高分辨率RGB图像。局部卷积全局一致性有限，Transformer处理高分辨率图像成本高；直接融合RGB纹理还会把颜色纹理误复制到深度图，造成边缘模糊或伪影。",
