    "experiments": "在NYU-v2、Middlebury、Lu及RGB-D-D等基准评估不同放大倍率。NYU-v2的×8 RMSE为2.39厘米，低于SGNet的2.44和HCGNet的2.53；×16为4.32厘米，优于表列方法。Middlebury×8为1.60厘米，Lu×8为1.42厘米。消融中NYU-v2×8基线RMSE 3.68厘米，加入SFCG、LHM和TCGE后完整模型为2.39厘米；Mamba骨干在3090上推理0.3108秒，RMSE 2.39厘米，CNN为0.1601秒/RMSE 2.46，Transformer为0.5862秒/RMSE 2.53。",
    "contribution": "方法将RGB纹理筛选、双域互补融合和结构残差先验连成一套重建流程，在×8、×16困难倍率多个基准上表现突出。作者讨论指出×4时并非所有数据集都占优；模型的运行时间受硬件与输入尺寸影响，且实验集中于配对RGB-D基准，跨传感器与错配场景的适用性仍需验证。\n---\nDOI: 10.1016/j.neunet.2026.109551",
