    "title": "Typed signed-monotone dual Choquet–Stieltjes networks for semantically constrained grouped prediction",
    "authors": "Jih-Jeng Huang、Chin-Yi Chen",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-08-29",
    "contentState": "complete",
