    "direction": "人工智能",
    "summary": "ContaminationAD借助CLIP伪标签估计训练图像污染并定位可疑区域，再以双专家表征和语义加权细化异常检测。",
    "question": "工业无监督异常检测通常假设训练集只含正常品，但实际数据可能混入异常样本；污染既会扭曲正常分布，也会拖累分类和像素定位，且污染比例变化使模型难以直接部署。",
    "method": "方法用预训练CLIP图像/文本编码器比较图像级与patch级分布，估计污染分数并聚类生成伪标签，同时产生粗粒度异常区域。伪标签将文本语义对应到不同视觉模式；双专家网络分别保留正常与异常模式信息。粗定位作为注意力引导，配合语义驱动的分割权重完成细粒度区域修正。",
    "experiments": "在MVTecAD、VisA、BTAD上按10%至50%污染比例评估分类和分割，并与PaDiM、PatchCore、SimpleNet、DestSeg、SoftPatch等比较。BTAD像素级AUROC平均值在10%、15%、20%污染下分别为0.943、0.940、0.938；作者的资源表报告冻结编码器150M参数、可训练2.8M参数，100轮训练40分钟，单图推理60.6毫秒（16.5 FPS），训练显存2.2 GB。污染增加时部分指标下降，效果随数据集和污染率而异。",
    "contribution": "工作把污染识别、粗定位和文本—视觉模式对齐整合到异常检测流程，在多种污染水平下保持较强分割表现，并给出推理效率数据。性能并非每类、每个污染比例都领先；依赖CLIP与聚类伪标签，且真实工厂污染分布和跨工厂迁移尚待验证（后一点是基于所报告实验范围的推断）。\n---\nDOI: 10.1016/j.neunet.2026.109567",
