    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1016/j.neunet.2026.109572",
    "direction": "人工智能",
    "summary": "OpenEnhancer以伪未知样本、特征专属稀疏层和注意力融合，缓解手工特征与深层特征适应冲突并提升未知类拒识。",
    "question": "多特征融合常在封闭集上训练，遇到训练时未见类别便可能过度自信；手工特征表达能力有限，深层特征又可能过拟合，混合时特征层级不一致。研究目标是在未知类别只于测试出现的开放集条件下保留已知类识别能力并提高拒识能力。",
    "method": "OpenEnhancer为不同类型特征配置特征专属稀疏学习层，将表征拆分为已知部分与伪未知部分；通过不同已知类样本混合生成辅助伪未知信号，帮助模型学习已知类别边界外的区域。各特征经多特征注意力融合，并以开放集目标联合训练。测试时依据已知类别置信分数区分已知与未知输入。",
    "experiments": "在NoisyMNIST、NUSWIDEOBJ、OutdoorScene、Animals、ESP-Game、MITIndoor六个多特征数据集上，以开放度0.1及0.1到0.5变化评估OSA、AUOSCR、CCR@FPR等，并比较多种融合方法。MITIndoor上OpenEnhancer CCR@FPR=10%为25.75；移除伪未知生成降至18.45，移除稀疏层时为11.76。随机Mixup在MITIndoor为21.66，低于显式跨类伪未知方案；部分基线因内存耗尽未能完成。",
    "contribution": "工作将伪未知训练和特征类型专属稀疏变换用于混合手工/深层特征的开放集识别，六个数据集实验及消融显示两组件对未知拒识有帮助。结果在不同特征集和开放度下有差异，且部分比较方法受内存限制；从所报告实验看，未知类与已知类高度接近、真实持续新增类别等场景仍需检验。\n---\nDOI: 10.1016/j.neunet.2026.109572",
