    "method": "SFMambaSR以空间—频率块为核心：空间域用视觉状态空间模块捕获长程依赖，结合多尺度特征提取保留局部纹理；频率域变换模块以小波分解增强高频缺陷信息。增强二维选择性扫描结合Hilbert曲线分形扫描与线性扫描，尽量兼顾空间连续性与非因果局部关系。整体针对晶圆显微图像设计轻量架构。",
    "experiments": "在自建大规模晶圆显微数据上比较×2、×3、×4放大倍率的PSNR/SSIM，论文报告各倍率PSNR最佳且SSIM具竞争力或领先，参数量807K。另在NEU-DET公开数据测试，并比较RTX 5090上的运行时间和显存。×2高斯噪声实验中，干净图像PSNR/SSIM为36.2992/0.8743；标准差5时为35.9844/0.8702，略高于SwinIR的35.9041/0.8697。",
