    "method": "ROLT 将当前窗口切成变量—时间片段作为查询，并从有界 FIFO 回放缓存检索相似的已标注历史片段，只把检索记忆附加到注意力的键和值上下文。LOLA 用共享可学习地标压缩上下文，并通过 Newton–Schulz 正交化稳定地标。MTSOL 联合近期未完全标注窗口的掩码监督、历史样本回放监督和教师蒸馏；教师周期性由学生刷新，在线缓存分为待标签区和已监督回放区。",
