    "method": "BAMFNet将图像拆为背景B与小目标T，借鉴低秩背景和稀疏目标先验构造可学习迭代更新。背景分支BFEM提取连续结构，GL-PAAM以局部/全局层级融合和patch注意力筛选关键背景区域；目标分支STEM以空洞卷积替代池化，模拟稀疏近端更新而不降低分辨率。MGFRM用1×1、3×3、5×5卷积汇聚细、中、粗粒度信息，逐阶段提升目标—背景对比。",
    "experiments": "在NUDT-SIRST、IRSTD-1k和SIRST-Aug上与传统低秩/局部方法及ACM、DNANet、UIUNet、SCTransNet、MSHNet等比较，评价mIoU、F1、检测率Pd和虚警率Fa。BAMFNet三集mIoU/F1/Pd/Fa分别为94.45%/97.14%/98.41%/1.22×10⁻⁵、66.05%/79.55%/91.40%/4.91×10⁻⁵、75.10%/85.78%/98.62%/30.71×10⁻⁵。SIRST-Aug合成背景干扰下虽有最高Pd，但Fa明显高于若干基线；消融和多粒度核分析用于检验模块作用。",
    "contribution": "贡献在于把背景抑制与微弱目标保留并列建模，并将低秩—稀疏分解思想转为端到端可学习迭代，再以多粒度重建融合。NUDT-SIRST上mIoU/F1达94.45%/97.14%，SIRST-Aug上检测率98.62%，但虚警率30.71×10⁻⁵，显示合成尖锐干扰可穿透背景先验并被目标增强分支放大；复杂背景仍是实质局限。\n---\nDOI: 10.1016/j.neunet.2026.109619",
