    "summary": "AttKLMS将核自适应滤波重写为查询—键—值注意力更新，使历史样本权重随当前输入学习，而非仅由固定核相似度决定。",
    "question": "KLMS在线预测依赖核函数度量当前输入与历史样本相似度，固定核宽度难以适应非平稳或高相关序列；标准核自适应滤波还可能在噪声下收敛慢或误差较大。论文研究是否能以可学习注意力权重改善历史信息选择，同时保持在线更新形式。",
    "method": "AttKLMS把当前输入视作查询、历史输入视作键、历史误差贡献视作值，通过可训练投影计算相关分数并经softmax归一化，再用注意力加权历史信息形成滤波输出和误差更新。作者还提出自注意力变体，并设计分段与连续特征提取流程用于多维序列；复杂度表中AttKLMS为O(i²)，高于标准KLMS的O(i)。",
