    "contribution": "论文将注意力解释为核自适应滤波的输入依赖历史加权机制，并以多种混沌/动态序列和高斯、脉冲噪声测试其误差表现。低MSE伴随二次级时间复杂度和较长实测训练时间；结果基于有限基准与仿真噪声，实际在线流数据的规模扩展、延迟约束和长期稳定性仍需检验。\n---\nDOI: 10.1016/j.neunet.2026.109625",
