    "contribution": "工作把脑网络关系编码进联邦异质图，并以 SE 权重提供候选影像解释。多中心比较显示较大站点子集表现较好；小站点结果较低或波动，且 F1 不占优，不能直接用于诊断。联邦训练不等于差分隐私，脑区解释仍需独立队列验证。\n---\nDOI: 10.1016/j.neunet.2026.109663",
