    "summary": "FGPass 将已知密码特征作为生成约束，GAFT 再利用首轮已匹配样本进行门控式适配；论文在多种离线评测情境中报告了命中率提升，并讨论其双重用途与局限。",
    "question": "既有定向密码模型较多利用用户个人信息，对密码本身已知特征的利用不足；不同服务的密码构造习惯和策略也存在差异，静态模型难适应目标域。论文考察特征约束能否改善生成结果，以及能否用有限的目标域反馈调整模型。",
    "method": "FGPass 在序列模型的概率估计与生成过程中加入软特征引导，使输出倾向满足指定约束；GAFT 使用首轮已匹配的样本对进行门控微调，在通用变换路径与目标域自适应路径之间逐步调节信息。实验将其与既有模型、无引导模型及标准全参数微调比较，并统计约束符合率、命中表现和计算耗时。作者说明数据在离线隔离环境中处理，敏感原始数据完成分析后删除，报告仅呈现聚合统计。",
    "experiments": "摘要报告 FGPass 在多种情境的平均命中率为28.30%，相较最佳对照提升20.81%；GAFT 相对首轮基线提升6.37%，相较标准全参数微调高48.08%。补充实验的8种情境、3档猜测预算共24个评估点中，特征引导模型在22个点达到最佳或并列最佳。约束符合率多数情境超过98%，但有一情境约15%的生成结果仍不符合约束。",
    "contribution": "工作把已知密码特征引入生成，并用门控适配处理目标域差异，评估命中、约束符合率和二阶段调整。作者指出其双重用途；实验基于选定的历史泄露数据，不能外推所有服务。特征相关性、少数情境的约束违例和耗时是实际限制。\n---\nDOI: 10.1016/j.neunet.2026.109646",
