    "method": "SMSyn 包含原型变分合成器 PVS 与特征空间保持模块 FSP。PVS 从历史身份原型统计采样，通过原型引导混合和变分生成合成特征，不储存原图；FSP 用中心收缩、原型知识蒸馏和结构蒸馏约束真实及合成特征，保持类别中心、原型邻居和局部关系。训练在多个数据域依序进行，并在两个域顺序下评估已见域抗遗忘与未见域泛化。",
