    "contribution": "SMSyn 把可控特征合成与嵌入几何约束结合，在不保留历史图像的条件下改善持续重识别，并在两个训练顺序及未见域基准上验证。其局限是特征级生成对外观变化的直接刻画不如像素级合成；论文也指出严重遮挡、杂乱背景或外观相似身份仍会损害排序。\n---\nDOI: 10.1016/j.neunet.2026.109649",
