    "summary": "合成梦境训练让模型以当前潜在表征为条件生成内部样本，并以可调权重混入真实数据目标，尝试拓展表征覆盖、改善泛化与抗扰动能力。",
    "question": "仅依靠外部训练样本会限制模型对分布外模式的泛化、抗扰性与生成多样性；传统生成回放主要重现旧数据以防遗忘。本文提出另一目标：生成不必对应既有样本、但与当前潜在状态相关的内部样本，作为探索式正则信号。",
    "method": "框架以潜变量 z=f(x) 表示当前输入，再采样高层变量 h，并由条件生成器 p(x̃|z,h) 生成梦境样本；混合目标在真实样本损失外加入由 λ 调节的梦境损失。论文以 Transformer 语言模型和条件变分生成器实例化，并比较标准训练与传统生成回放；评估语言困惑度、稀有模式分布外测试、输入遮蔽鲁棒性、n-gram 多样性，以及 Permuted MNIST 连续学习表现。",
    "experiments": "语言建模表中，基线测试/OOD困惑度为29.4/42.1，传统生成回放为26.8/37.5，合成梦境为24.9/34.2；n-gram 熵从基线3.41升至3.76，噪声鲁棒指标从0.59升至0.81。摘要另报告10%遮蔽下性能退化约由41%降至19%。Permuted MNIST 上合成梦境最终平均准确率与生成回放相近，而非显著取代回放。",
    "contribution": "论文提出状态条件的内部样本探索，并用 λ 调节其学习权重；语言建模支持泛化、多样性和抗遮蔽能力改善，连续学习表现与回放相当。证据主要来自单一语言模型和合成基准，不能据此断言通用模型都会获益；梦境质量、权重选择及大规模评估仍是限制。\n---\nDOI: 10.1016/j.neunet.2026.109664",
