    "method": "DECL 包含多样性增强图像模块 DIA、特征提取器和多样性感知对比模块 DCL。DIA 用多分支增强和跨样本拼接构造变化丰富的图像组合；提取器编码增强视图；DCL 以类别原型组织监督对比，并结合跨尺度对齐，让同类特征聚合、异类分离。实验在 CIFAR-LT、ImageNet-LT 与 iNaturalist 2018 上比较长尾基线，并通过模块消融检验 DIA、DCL 和尺度项。",
