    "question": "kNN、随机森林和核 SVM 等非光滑分类器没有可靠梯度，常规反事实搜索难以直接优化；代理模型虽可提供梯度，却会扭曲特征空间距离，映回原空间后可能失效或不真实。研究目标是同时约束代理忠实度、反事实有效性与原空间邻近性。",
    "method": "ECOer 先用双 ReLU 结构 R2SNN 拟合黑箱边界，并以边界感知采样改善代理；再学习特征到输入的线性重构映射，加入保距正则限制代理变换造成的度量偏差。利用 R2SNN 分段线性决策区域，将反事实目标按区域凸松弛求解，并用贝叶斯优化选择正则参数。实验覆盖6个表格数据集、3类黑箱分类器和多个基线。",
