    "contribution": "方法把代理边界拟合、输入空间度量保持和区域凸优化串成后验解释流程；多数据集、多分类器评估同时考察有效性、邻近性和分布合理性，而非只报告距离。仍需注意结果取决于代理近似和重构映射；论文指出 ECOer 并非所有方法中最快，且黑箱模型与数据分布改变时解释质量需重新验证。\n---\nDOI: 10.1016/j.neunet.2026.109793",
