    "question": "低照度增强常因照明估计不准而出现整体曝光失衡；增强同时放大噪声，单靠像素级恢复又可能损伤物体细节和语义外观。作者提出在空间、频率与语义表征间传递互补信息，缓解亮度、噪声和语义一致性之间的冲突。",
    "method": "SFSNet分三阶段处理输入。AIENet以可学习照明参数自适应估计全局曝光；DNRNet在空间域去噪，并用Haar小波分解高频子带、分别处理后融合，以抑制增强放大的噪声并保留细节；SGNet利用预训练CLIP视觉嵌入作为语义查询，与空间特征交叉注意力融合，校正增强结果的语义表达和颜色。",
