    "contribution": "方法把照明估计、小波域降噪和预训练视觉语义引导组合为统一增强流程，并在三个LOL测试集取得表内领先指标。语义编码器和三阶段网络增加模型复杂度；像素指标不能完全代表真实场景偏好或下游视觉性能，论文以LOE和定性结果补充评估。跨设备及真实照明分布的泛化仍需检验。\n---\nDOI: 10.1016/j.neunet.2026.109846",
