    "question": "视觉Transformer自注意力随token数呈二次增长，高分辨率时计算和显存成本突出。既有方法依赖不同模型或任务分类，难以横向理解它们如何利用空间冗余、又在哪些任务上容易损失信息；本文试图建立按实现机制组织的统一视角。",
    "method": "作者按实现机制归纳三种范式：窗口法依据邻近性限制交互，动态缩减法按内容重要性筛选或合并token，潜在空间法将表示压缩到固定数量潜在token。综述细分窗口移动、层级合并和邻域扩展等机制，并比较复杂度、精度、任务适配和部署条件；量化表汇总文献中的ImageNet-1K及检测、分割、超分结果。",
    "experiments": "本文是综述，不提出单一新模型或统一受控实验；量化结果来自设置不同的文献。例子包括COCO检测Swin-L+HTC++为57.1 box AP，所列ATS-DETR为48.9；实例分割Swin-L为49.5 mask AP，所列最佳潜在空间方法为43.2；Urban100×4超分中HAT为27.97 dB PSNR。作者据此讨论空间细节任务对压缩的敏感性。",
    "contribution": "统一框架将策略对应到几何、语义和表示冗余，解释精度—算力权衡：窗口结构规整，动态路由更自适应，潜在空间计算量可与输入分辨率解耦。结论是文献综合而非同条件排行榜；密集预测和低层视觉证据较少，FLOPs也不能完整代表硬件延迟，训练成本缺少系统比较。\n---\nDOI: 10.1016/j.neunet.2026.109837",
