    "method": "框架包含领域感知适配器库（DAAB），由输入相关软路由组合多个适配分支；双结构多时间尺度优化让适配器快速吸收当前域及少量回放样本，外循环则将更新投影到受约束子空间以巩固共享参数。选择性记忆刷新（SMR）基于子空间信息替换回放缓存中的样本，兼顾保留旧域知识和纳入新域信息；推理时无需领域标签。",
    "experiments": "在P-MNIST、R-MNIST、CORe50、DN4IL四个领域增量基准上与重放、正则化和适配器方法比较；记忆基线统一为500个样本。表1中完整方法平均准确率分别为94.89±0.25%、95.23±1.62%、89.72±1.04%和52.36±0.35%，四项均高于表列基线。DN4IL记忆预算从500降至50时，作者报告其相对次优方法的最大差距达6.81个百分点；组件消融显示DAAB、优化策略和SMR均有贡献。",
    "contribution": "工作通过结构和优化两层分离领域专门化与跨域泛化，并以SMR针对有限缓存进行动态知识保留；实验覆盖合成旋转数据和真实图像域。主要证据来自有限基准、特定回放预算和CNN/MLP骨干，不能直接推广到所有模态或任务。作者另报告预训练ViT迁移结果为补充设置；主方法训练需要外循环及投影操作，计算开销高于简单微调。\n---\nDOI: 10.1016/j.neunet.2026.109855",
