    "summary": "KGPC将医学知识证据和临床表达结构引入医患对话生成，并用相似病例提供结构约束，旨在提高回复的事实依据与组织连贯性。",
    "question": "既有医学对话模型常依赖对话中明说的实体，容易漏掉由症状、时间变化和医学关联暗示的临床线索；自由生成又未显式模拟医生从病史整理到评估、计划的过程。论文聚焦如何补全患者状态，同时避免知识图谱噪声，并让回答结构更符合临床推理。",
    "method": "知识增强模块从对话抽取显式实体，再用医学知识图谱和时间信号扩展隐含、演变线索，构成异质患者状态图；层级检索以“评分—剪枝—扩展”筛出与当前语境相关的知识路径。结构约束模块将对话转成SOAP表示，检索临床状态相似的SOAP记录并聚合其结构特征。生成器联合使用对话、知识路径和可学习结构信号，因此无需固定模板也能获得证据支撑与组织引导。",
    "experiments": "作者在MedDG、KaMed、MedDialog和MediTOD四个公开语料上，以LLaMA3.1-8B为骨干，与对话、推理及知识增强基线比较，并进行人工评价、模块消融和骨干迁移分析。MedDG上KGPC的BLEU-1为58.27、ROUGE-L为44.31；对照最强基线BP4ER分别提高8.95和15.42个绝对分值。KaMed的SOAP质量评审中，覆盖、正确性、一致性分别为4.04、3.68、3.73（五分制）。",
    "contribution": "工作把患者状态补全、对话感知的知识路径检索和SOAP结构约束整合进同一生成流程，并在四类语料及多种开源骨干上验证。消融显示RPC移除后MedDG的ROUGE-L下降5.19，KE移除后实体F1下降2.88，支持结构和知识模块各自发挥作用。结果衡量的是语料匹配、评审与离线生成质量；临床部署效果仍需独立验证。\n---\nDOI: 10.1016/j.neunet.2026.109866",
    "sample": false,
    "id": "r-1o8k3ge",
    "tags": [
      "医学AI",
      "自然语言处理",
      "大模型"
    ]
