    "link": "https://doi.org/10.1016/j.neunet.2026.109900",
    "direction": "人工智能",
    "summary": "该方法以多簇储备池回声状态网络逼近严格反馈非线性系统的不确定项，并将自适应反步控制改为事件触发更新，以兼顾执行器故障下的稳定跟踪与较低控制频率。",
    "question": "严格反馈非线性系统存在建模不确定性、耦合非线性和执行器完全或部分失效时，常规神经自适应控制仍可能频繁更新控制量，增加计算负担。作者希望借助有簇结构的储备池表示非线性动态，并用事件触发机制减少控制动作，同时证明故障条件下闭环信号保持有界。",
    "method": "控制器采用反步设计，使用多簇回声状态网络（MR-ESN）近似未知非线性项。储备池隐藏节点划分为多个功能簇，簇内连接较密、簇间耦合较疏，并使用不同激活函数；网络结构离线构造，在线主要自适应输出权重。事件触发条件依据跟踪误差和动态阈值决定是否刷新控制及网络状态，非触发期间保持最近一次发送值。Lyapunov分析给出一致最终有界结论，其成立依赖储备池谱半径、初值有界等假设。",
    "experiments": "论文以数值仿真测试三阶非线性系统，模拟执行器按阶段经历正常、完全失效和部分失效，并观察系统状态、控制输入、权重更新和触发时刻。结果图显示控制器在故障切换期间仍维持稳定响应；触发式控制频率低于Nie与Wang（2024）的对照控制器。分析定理在储备池谱半径小于1、初值有界及增益满足条件时证明系统信号一致最终有界。该文报告的是仿真验证，没有实体系统实验或统一数值误差表。",
    "contribution": "方法的特点是用多簇储备池和异质激活函数表达耦合非线性，同时冻结大部分储备池结构、只更新输出权重，并按误差事件调度控制。理论分析提供带条件的稳定性保证，数值故障场景展示控制频率下降与故障适应性。证据范围限于所设三阶模型及模拟故障；效果对储备池结构、触发参数和假设条件有依赖，不能据此断言实际硬件、未建模故障或噪声环境下同样有效。\n---\nDOI: 10.1016/j.neunet.2026.109900",
    "sample": false,
