    "doi": "10.1016/j.neunet.2026.109875",
    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1016/j.neunet.2026.109875",
    "direction": "人工智能",
    "summary": "ADRMD用多模态智能体围绕事件发展提出并质疑预测，再整合视觉、文本和时间证据，生成自然语言事件预测。它同时依据事件内容动态指定讨论角色，并用语义评价器评估预测与实际观察的匹配程度。",
    "question": "不少事件预测方法输出离散标签或孤立语义单元，难表达事件中人物、行动、对象及上下文关系；单个模型也可能遗漏冲突证据。作者试图把多模态线索组织成可审视的预测过程，并考察角色分工、辩论和整合是否能提高预测与真实后续事件的语义吻合度。",
    "method": "视频被整理为按时间排列的关键帧及文本描述。视觉语言模型根据事件特征指定专业角色；提议者形成带证据的假设，挑战者审查逻辑和时间连贯性并提出反驳，系统再经过分歧、协调、整合三个阶段形成预测。评估阶段由模型比较自然语言预测和观察结果的语义一致性。论文还比较移除辩论模块的版本，并记录推理成本。",
    "experiments": "评估围绕1000个事件样本，使用多名人工评审及多模态模型评分，并对比若干既有方法。论文表中ADRMD-1与ADRMD-2的Top-1分数分别为33.34%和31.06%，Top-5为44.93%和52.14%；这些分数来自其五级语义评分协议，不等同于常规分类准确率。另一个运行审计中，辩论版平均每事件耗时56.74秒、5547.5个token；无辩论版为16.30秒、1279.8个token。",
    "contribution": "工作将动态角色、跨模态证据和显式质疑整合为事件预测流程，并把自然语言输出纳入语义评价；无辩论对照为讨论环节的作用提供了实验切口。其代价也清楚：加入辩论后推理时间和token消耗显著增加，适用性取决于任务是否允许额外推理和讨论时间。数据聚焦特定制造维修事件，论文指出还需扩大负载以评估持续运行中的延迟与可靠性。\n---\nDOI: 10.1016/j.neunet.2026.109875",
    "sample": false,
    "id": "r-1h4568",
    "tags": [
      "多模态学习",
      "大模型",
      "时间序列与预测"
    ]
