    "title": "Closed-form continuous-time neural networks for cognitive regime recognition",
    "authors": "Zihan Lin",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-11-09",
    "contentState": "complete",
    "contentNote": "已基于出版社正式版全文完成中文六段式总结，正文在出版社页面获取",
