    "link": "https://doi.org/10.1016/j.neunet.2026.109878",
    "direction": "人工智能",
    "summary": "论文将闭式连续时间网络用于认知状态识别，并以耦合矩引擎生成具有物理动力学结构的认知轨迹。其“认知时间”机制根据模型预测熵调节有效时间常数，使状态在不确定时演化较慢、较确定时演化较快。",
    "question": "常见LSTM、GRU按固定离散步长处理序列，难以表达认知活动在探索、专注等状态间以不同速度演变的假设。作者提出用连续时间状态表征认知过程，并检验这种表示能否识别合成轨迹及跨被试EEG状态，同时考察熵调节时间常数是否带来鲁棒性。",
    "method": "耦合矩引擎以双向Landau–Lifshitz–Gilbert动力学生成12维认知状态轨迹；闭式连续时间网络通过双候选状态和门控插值更新隐藏状态。有效时间常数设为τeff=τbase(1+βH(p))，由预测分布的香农熵H(p)调节。实验分为仅用引擎状态的合成Track A，以及融合引擎状态与EEG频谱特征的Track B；后者采用留一被试交叉验证。",
    "experiments": "Track A只有60个结构化合成样本，五折验证中四类状态达到100%，而同设置的LSTM、GRU和MLP为50%；论文明确将其视为概念验证，不能代表真实认知任务。Track B融合31名受试者的105维输入，在13,294个窗口上留一被试评估，三类EEG识别平均准确率75.9%，标准差20.8%，高于33%的机会水平。作者也报告CfC每步计算量较高，且未完成认知时间机制在完整EEG数据上的消融。",
    "contribution": "研究把连续时间闭式网络、物理启发的双向动力学输入和基于预测熵的时间调节用于认知状态识别；合成和EEG两条评估轨道区分了机制可行性与真实跨被试表现。主要证据是合成轨迹上的架构比较及EEG跨被试结果。合成集很小且轨迹可分性强；EEG个体差异明显，因而100%结果不可泛化，认知时间对真实EEG准确率的独立贡献仍未由完整消融证实。\n---\nDOI: 10.1016/j.neunet.2026.109878",
