    "summary": "CCAV先从支持图像归纳共享的物体语义与关系概念，再逐级核验查询图像，在复杂概念少样本分类中优于多种对照。",
    "question": "复杂概念分类的正负图像可能包含相同物体，区别在属性、交互或关系；静态原型难以判断任务关注何种共性，测试时也未必有新概念文本。本文将支持集概念归纳与查询验证分开，并把语言监督限于训练阶段。",
    "method": "CCAV由共同概念聚合（CCA）和查询概念验证（QCV）组成。CCA以支持集自注意力形成任务级物体语义锚点，再以其条件化关系敏感表示；训练时分别对齐物体描述和完整交互描述。QCV依次用两种表示条件化查询特征。测试无需文本编码器。作者说明这些潜表示不是实例检测或显式符号规则。",
    "experiments": "在ShapeWorld、Bongard-HOI、Bongard-OpenWorld上与少样本及视觉语言方法比较，并做模块替换和敏感性分析。ShapeWorld准确率73.58%±1.07%（95%置信区间），所列最强基线71.32%±1.04%。Bongard-HOI三次运行均值90.36%±0.35%（样本标准差）；OpenWorld四子集平均67.6%，比GPT-4报告值高6.0个百分点，但训练和推理资源不同，作者仅作基准背景比较。",
    "contribution": "Bongard-HOI上完整模型为90.56%；CCA换均值池化降至83.62%，QCV换余弦原型匹配降至74.71%，支持两模块在该协议下有用，但不证明语义解释的因果真实性。局限是依赖训练期语言监督，噪声支持集、分布偏移或编码器未表征的新实体可能削弱迁移；模型也不输出实例定位或可读规则。\n---\nDOI: 10.1016/j.neunet.2026.109903",
