    "title": "Real-time multiplierless FPGA implementation of a spiking cerebellar neuroprosthesis for oculomotor disorders rehabilitation",
    "authors": "Xiaotian Pan、Xinyue Chen、Chaochao Wang 等",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-11-09",
    "contentState": "complete",
