    "direction": "人工智能",
    "summary": "作者将误差调制的脉冲时序依赖可塑性（STDP）用于小脑式脉冲控制器，并以无乘法器FPGA实现，在合成眼震模型上实现闭环抑振。",
    "question": "眼球震颤等病理振荡会使视网膜图像不稳定，传统控制难以适应时变扰动；而软件仿真无法证明神经形态控制能否满足植入设备的延迟、面积和功耗约束。研究关注如何把在线学习的脉冲小脑控制器实现为资源受限硬件，并检验其控制表现。",
    "method": "系统把眼球动力学与脑干基线控制器、随机高斯脉冲编码器、60个时分复用的泄漏积分发放（LIF）虚拟神经元及片上STDP学习引擎组成闭环。STDP由误差信号调制以学习抵消振荡的反相控制。数据通路采用16位Q4.12定点表示，用桶形移位器近似乘法、查找表实现相关运算，并用20位累加和饱和逻辑处理中间值；因此无需DSP乘法器。",
    "experiments": "作者先在数学眼球模型中模拟2.5 Hz、振幅2.5°扰动，再将设计综合并部署到Xilinx Virtex-6 XC6VLX240T FPGA，进行定点功能验证、资源、时序与功耗评估，并以PID、标准机器学习控制器和浮点SNN作比较。硬件在4 Hz条件下将峰峰振幅从3.00°降至0.056°，衰减率98.1%，收敛时间小于250 ms，输入输出延迟1 ms。50次随机种子评估中，频率1.5–6 Hz、振幅1–4°各组合的平均抑制效率均超过95%，95%置信区间最大半宽小于0.5%。200 MHz下动态功耗16 mW；占用342个寄存器、586个LUT，DSP48E1为0。",
    "contribution": "工作把误差驱动的在线STDP与移位、查表等硬件运算结合，给出可实时运行的小脑式自适应抑振原型。定点FPGA的RRMSE接近浮点SNN：在6 Hz情形分别为1.29%和1.22%。证据边界也很清楚：测试对象是合成数学眼球模型，并非患者生理信号或体内实验；作者将真实眼电记录、眼动反馈、多自由度控制列为后续工作，故结果支持硬件可行性，不能视为临床疗效验证。\n---\nDOI: 10.1016/j.neunet.2026.109885",
    "sample": false,
    "id": "r-1stb6ot",
