    "link": "https://doi.org/10.1016/j.neunet.2026.109891",
    "direction": "信息安全",
    "summary": "FSS-Attack将稀疏中频预处理与多尺度、跨编码器的全局—局部语义对齐结合，在黑盒条件下提升针对闭源多模态大模型的定向迁移效果。",
    "question": "闭源多模态大模型的结构和梯度不可访问，现有可迁移攻击常把频域扰动与空间语义对齐分开处理，难以同时保留可感知质量并让目标语义跨不同模型生效。研究考察频率敏感视觉线索与层级图文语义的交互能否改善黑盒迁移攻击，并评估其对输入预处理防御的稳健性。",
    "method": "FSS-Attack先以稀疏中频频域预扰动形成图像锚点，再通过多尺度裁剪和层级集成对齐，在多个开源视觉—语言代理编码器间结合全局场景与局部目标语义进行优化；闭源受测模型仅用于迁移评估。论文还比较不同频带、模块组合和输入防御下的攻击成功率、目标语义相似度及图像感知质量。以下仅概述其评估机制，不展开可执行攻击配置。",
    "experiments": "实验以1000组图像和目标图像配对评估闭源、开源及推理增强型模型，主要指标为攻击成功率（ASR）、目标语义相似度及LPIPS/SSIM。闭源模型上，FSS-Attack在GPT-5的ASR为79.7%，优于FOA-Attack的74.9%；在Gemini-2.5-Flash为66.3%，优于54.8%。对开源模型LLaVA-1.6-7B，ASR为74.0%，FOA-Attack为72.6%。消融显示在LLaVA和Gemini上完整模型ASR分别为78.6%与63.0%，去除频域预处理后为75.0%与57.3%。",
    "contribution": "贡献是把频率预处理与跨尺度语义对齐作为协同机制分析，而非只在单一表示空间寻求扰动；频带干预与消融结果支持中频线索和层级对齐共同影响迁移表现。效果并非对所有模型一致：Claude系列闭源模型上的ASR明显低于GPT与Gemini，作者也无法从不可见的内部结构确定原因。输入级平滑和压缩只能部分削弱结果；测试依赖特定模型、提示和自动语义评分，不能据此推断所有真实使用情境的脆弱性。\n---\nDOI: 10.1016/j.neunet.2026.109891",
