    "direction": "人工智能",
    "summary": "该深层置信规则系统按特征重要性把全局输入分配给多层局部规则库，共享跨层参数、从数据聚类生成规则，并逐层融合信念分布以控制规则组合膨胀。",
    "question": "置信规则库能用可读的IF-THEN规则表示不确定性，但输入维度升高时，属性等级组合会造成规则数量爆炸；多层BRB若逐个迭代调参，建模成本也会增加。作者研究如何保留全局特征信息和分层推理，同时自动生成较紧凑规则并减少参数优化。",
    "method": "方法由三部分构成：先依据特征权重，通过带放回加权采样和权重衰减（WSR-WD）将重要全局特征分配到多个局部BRB；再跨层共享同一特征的属性权重、效用值和信念分布，将数据映射到信念空间并聚类生成规则，免去逐规则参数优化；最后使用证据推理算法逐层融合各BRB输出的信念分布，完成分类或回归。该设计允许多个BRB复用特征知识，而每层只处理有限特征子集。",
    "experiments": "在4个回归数据集和14个分类数据集上，与传统规则系统、机器学习及深层模型比较，并做组件消融和超参数分析。与深层规则模型比较时，分类准确率的平均排名为1.80；THY数据集准确率为93.17%±0.21%，使用23条规则，而仅用6条规则的FURIA-BRBCS为58.72%。多分类消融中，移除规则聚类后平均准确率由58.08%降至51.51%，移除堆叠结构后为57.73%，支持两项设计的作用。",
    "contribution": "研究将全局特征筛选、层间参数共享、免迭代规则生成和证据推理串联，在维持可追踪规则结构的同时缓解高维建模成本。消融显示聚类规则生成和堆叠组织对多分类表现及效率尤其重要；但准确率与规则规模存在折中，THY示例中23条规则换取明显高于6规则基线的准确率，高维MAD上规则数甚至达到811。层数和每层特征上限对结果影响非单调，需按数据选择；自动决定层级、应对类别不平衡仍是后续问题。\n---\nDOI: 10.1016/j.neunet.2026.109902",
