    "title": "TVTTP: Task-specific visual tracking based on trajectory prompts",
    "authors": "Mengting Zhang、Runkai Hua、Qun Li 等",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-11-09",
    "contentState": "complete",
    "contentNote": "已基于出版社正式版全文完成中文六段式总结，正文在出版社页面获取",
    "doi": "10.1016/j.neunet.2026.109883",
    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1016/j.neunet.2026.109883",
    "direction": "人工智能",
    "summary": "TVTTP将连续帧中的目标位置历史编码为时空轨迹提示，辅助视觉跟踪器预测目标运动，并通过IoU感知分类分数缓解分类置信度与边界框质量不匹配。模型还结合级联框细化和统计模板更新，以应对干扰物、遮挡及外观变化。",
    "question": "视觉跟踪器常依据分类分数选择候选框，但高分类置信度不一定对应准确定位；仅用当前帧外观也难应对相似干扰物和短时遮挡。本文研究如何在跟踪过程中利用目标轨迹连续性提供运动先验，并让分类头的评分与边界框回归质量保持一致。",
    "method": "轨迹提示模块将历史预测框映射为当前搜索区域的时空高斯提示，供网络融合连续运动信息；IoU感知分类分数（IACS）让分类分数反映预测框与真实框的重叠质量。级联结构逐步细化边界框，动态模板更新则依特征统计阈值维护目标外观。训练分阶段进行，先帧级学习，再用连续视频片段学习轨迹，最后训练模板更新。",
    "experiments": "作者在GOT-10k、TrackingNet、LaSOT、UAV123、NFS30等基准上比较现有跟踪器，并开展模块消融。GOT-10k上AO为76.0%、SR0.5为86.5%、SR0.75为73.5%；AO较MixFormer高1.7个百分点，但MixFormer使用多个训练集，而本文该项按GOT-10k训练集协议训练。TrackingNet AUC为84.9%，与最佳报告值并列；LaSOT AUC为69.9%，与MixFormer接近。移除轨迹预测后GOT-10k AO下降1.2个百分点。",
    "contribution": "工作把历史位置轨迹作为显式提示，并以IACS将分类决策与框回归质量对齐，结合级联细化及基于统计量的模板更新。消融支持轨迹预测和模板更新在基准跟踪中的作用。论文同时展示全遮挡、目标离开视野和快速运动时的失败：历史位置失效或突变会让提示误导定位，因此运动先验仍需依赖目标可见性及轨迹稳定性。\n---\nDOI: 10.1016/j.neunet.2026.109883",
    "sample": false,
