    "link": "https://doi.org/10.1016/j.neunet.2026.109884",
    "direction": "人工智能",
    "summary": "AEVR-GSL将变分边重构与分类目标联训，并以分类损失梯度修正节点特征，在八个节点分类基准上改善图结构学习效果，尤其适用于异配图。",
    "question": "图神经网络通常依赖给定邻接关系，但真实网络可能稀疏、含噪或与任务不匹配；仅凭特征相似度推边也未必服务于下游分类。作者希望从节点特征中探测潜在连接，并让学得结构与消息传递和分类目标直接协同。",
    "method": "AEVR-GSL以变分自编码器将节点特征映射到潜在空间，通过特征融合、扰动及潜变量解码重构候选边，并在重采样候选边上学习稀疏图。分类器的监督信号隐式提供任务信息；模型进一步固定网络参数、依据分类损失对输入节点表示作梯度更新，再用增强表示重建图。训练采用协同优化，并设置早期结构更新阶段与后续稳定阶段，避免频繁改图破坏已学结构。",
    "experiments": "在Cora、Citeseer、Pubmed、Minesweeper、BlogCatalog、Amazon-Ratings、Flickr和Roman-Empire八个真实或基准数据集上进行节点分类，对比多类图结构学习方法，并做结构更新与组件消融。Pubmed（19,717个节点）准确率为85.14%；Amazon-Ratings（24,492个节点）为50.31%。BlogCatalog上准确率为83.47%，相较文中所述传统图神经网络基准73.18%高10.29个百分点。作者报告异配数据上的整体优势及对特征噪声、结构扰动的稳健性。",
    "contribution": "方法的关键在于把结构推断、分类监督和特征反向修正纳入同一训练链路，使图结构不仅拟合特征共现，也能回应分类损失。消融结果显示变分重构和结构更新是主要收益来源，早期更新策略也有较小的稳定化贡献。作者指出，采样式训练可能改变真实结构分布，且异配图上的结构学习解释仍不足；未来需加强可解释性并改进稀疏结构构造。\n---\nDOI: 10.1016/j.neunet.2026.109884",
    "sample": false,
