    "direction": "人工智能",
    "summary": "PHM把图像映射到预先筛选、满足引物约束的四元DNA哈希码集合，并以最优传输对齐图像与码本，在保证生物兼容性的同时实现有竞争力的检索精度。",
    "question": "DNA存储规模扩大后，需要能按内容检索的编码方案。常规深度哈希直接学习二值码，未必满足DNA引物的碱基比例和连续重复限制；即使把这些条件作为损失约束，也难以保证生成码可实际使用。作者希望将检索限定在预先构造的生物兼容码本内，同时避免码本缺乏语义导致图像与码无法有效匹配。",
    "method": "PHM先生成满足GC含量40%–60%、同聚核苷酸长度不超过4等条件的四元DNA候选码，再转为二进制表示。冻结预训练图像编码器，仅训练轻量哈希编码器及分类器。最优传输（OT）分两步提供监督：依据码的汉明空间结构为码本产生伪标签，再对齐哈希码嵌入与图像特征；类别不兼容的图像—码配对在运输代价中加惩罚。作者另提出HDC指标，统计数据库集中分配到最常用代码的比例，以补充mAP对码本利用率的观察。",
    "experiments": "在CIFAR-10与ImageNet上评估检索精度、代码集中度和资源开销，并与无生物约束的深度哈希方法比较。使用ViT骨干时，PHM在CIFAR-10的mAP为0.940、ImageNet为0.874；更强骨干下分别可达0.987和0.932。ImageNet默认码本配置包含9,148个候选码，mAP@1000为0.874、HDC@100为61.04%。PHM-ViT训练峰值显存为0.05 GB，低于表中VTDH-ViT的3.37 GB；但其检索精度并未在所有设置中超过不受DNA约束的基线。",
    "contribution": "PHM将生物约束放在候选码本生成阶段，再用OT把没有天然语义的代码组织成可与图像类别对齐的嵌入，避免图像特征提取器参与反复训练；HDC则揭示mAP未呈现的代码使用集中现象。局限是码本的生化约束限制了同类紧凑性与跨类分离之间可同时达到的程度，性能因此未必赶上直接学习的无约束哈希。实验还显示放宽筛选会改变码本大小、跨类几何和HDC，mAP并非随候选数单调变化；实测为计算机基准与in-silico评价，不能单独证明湿实验PCR检索性能。\n---\nDOI: 10.1016/j.neunet.2026.109890",
