    "summary": "DETND将事件触发通信与分布式神经动力学求解器结合，在满足机械臂关节约束的同时减少多机械臂协同跟踪中的控制信息更新。",
    "question": "多机械臂协同跟踪需要邻居间频繁交换状态和控制信息；固定周期通信会占用带宽并可能降低网络可靠性，而关节位置、速度约束又必须纳入控制。作者研究如何在保持速度一致和轨迹跟踪的前提下，仅在误差条件需要时更新信息，并避免求解过程出现参数无界增长。",
    "method": "作者以无向图描述机械臂间通信，将末端运动一致性、期望轨迹和关节位置/速度约束写入分布式最小速度范数优化问题。使用Fischer–Burmester互补函数表达约束最优性条件，再构造神经动力学求解器；事件触发机制根据协同位置误差决定何时更新并传送控制信息，从而只在需要时计算与通信。理论部分分析误差收敛及参数有界性，实验以四台机械臂执行玫瑰线和雪花线协同跟踪。",
    "experiments": "作者进行仿真和实体机械臂实验，并与周期触发、VP-RNN及ZNN方案比较。雪花线任务中，事件触发下四台机械臂的信息更新次数分别为17、5、2、4次；周期触发方案每台均更新1001次。表中最大协同位置误差分量在DETND下约为1.21×10⁻¹³至5.31×10⁻¹³ m，低于比较方法对应值。实体实验显示四臂可跟踪玫瑰线与雪花线，雪花线实验还包含外部扰动；对比表中物理执行时间DETND为116.18 s，VP-RNN为117.52 s，ZNN为182.58 s。",
    "contribution": "方法把受约束的分布式协同运动规划转为神经动力学在线求解，并用事件条件压低冗余通信；仿真与实体平台结果都展示轨迹协同能力。证据主要来自四机械臂、两类轨迹和给定通信拓扑，不能直接推出更大规模网络、不同硬件或长期运行中的带宽与可靠性表现。作者将恶意网络攻击下的韧性协同控制列为后续方向，因此本文未验证受攻击通信环境下的安全性。\n---\nDOI: 10.1016/j.neunet.2026.109896",
