    "direction": "信息安全",
    "summary": "vEcho将静态扫描告警审计扩展为基于代码证据的迭代发现，并把已确认和排除案例转为后续搜索指引。",
    "question": "静态应用安全测试能高召回地产生候选告警，但有误报，也会漏掉框架分发、间接传播和业务逻辑等问题。单次大模型核验既受扫描器范围限制，也不能复用核验经验；作者希望结合可追溯审计与主动搜索。",
    "method": "vEcho保留SAST作为候选来源，由ScanAgent在仓库内按范围搜索静态分析盲区，形成带文件和代码位置的候选；VerifyAgent在持久化案件状态中检查攻击者可控输入、传播路径、危险操作及有效防护，证据不足时标为未知。Echoic Vulnerability Propagation（EVP）把已确认或排除案例提炼为有类型的线索，指导后续重扫；新案件仍须独立核验证据。",
    "experiments": "在CWE-Bench-Java的120个漏洞实例上，与IRIS等基线评估。vEcho检出73/120（60.83%），IRIS检出50/120（41.67%）；平均F1为0.3974，对比IRIS的0.1166。阶段分析显示SAST被动筛查检出29个，加入证据审计后累计59个，再加入EVP累计73个，后两阶段分别新增30和14个。论文另报告跨21个开源项目负责任披露52个漏洞，其中25个获CVE编号。",
    "contribution": "工作把审计从告警过滤变为有代码证据约束的闭环发现，并展示额外检出。结论限于Java仓库及该基准；代理搜索耗费较多令牌，复杂业务语义仍可能误判，跨项目迁移评估尚待建立。检出数不等同实际部署覆盖率。\n---\nDOI: 10.1016/j.cose.2026.105236",
