    "summary": "P-BASE并行建模AAL与CC200脑区图，以时空图卷积提取局部动态、Transformer捕捉全局依赖，再融合两套表征用于自闭症分类。",
    "question": "静息态fMRI的静态功能连接会掩盖脑区间随时间变化的互动，而单一脑区图谱也难以覆盖脑组织的多尺度组织结构。研究探讨能否结合动态连接和互补图谱，同时建模局部时空波动与远距离全局依赖，以提升自闭症谱系障碍（ASD）分类表现。",
    "method": "P-BASE将ABIDE静息态BOLD信号分别按AAL和CC200图谱划分为116、200个脑区，以滑动窗口构造动态功能连接图。每个图谱使用并行局部—全局编码分支：时空图卷积网络提取邻近脑区的局部时序模式，Transformer建模跨脑区长程关系；Sero读出按节点重要性汇聚图级表示，最后融合双图谱特征并分类。实验还以静态连接、单图谱及替代读出方案作消融和比较。",
    "experiments": "在ABIDE的NYU与UM站点分别评估，并报告跨站点迁移。NYU站点准确率、AUC分别为0.73±0.03、0.80±0.03，UM为0.75±0.04、0.79±0.04；比较表中表现较强的MDGL准确率分别为0.71±0.05和0.71±0.03。跨站点NYU→UM时准确率0.70±0.03、AUC 0.73±0.04，反向UM→NYU为0.67±0.09、0.69±0.11，性能有所下降。移除双图谱、动态窗口或局部—全局并行编码均导致表现下降。",
    "contribution": "方法的主要价值在于同时保留两种分区方案的互补连接信息，并将局部动态与全脑长程关系纳入同一表示。站点内结果优于多种基线，但跨站点指标更低且存在方向不对称，显示域迁移仍是现实限制。作者也指出，注意力权重只表示模型用于预测的功能模式贡献，不能解释为因果神经机制；图谱选择会影响所建网络，临床生物标志物意义仍需神经生物学研究验证。\n---\nDOI: 10.1016/j.neunet.2026.109898",
