    "direction": "人工智能",
    "summary": "CLEAR以局部概念逐级引导全局语义概念，并聚合不同强度视图下的图像证据，旨在同时缓解概念瓶颈的分类性能损失与热图不稳定。",
    "question": "概念瓶颈模型可用语义概念解释医学图像分类，但把不同粒度概念平铺预测会削弱视觉表征与概念的对应；常见后验热图又会随亮度、对比度等输入变化而漂移。作者希望让局部病理线索参与全局判断，并提供对轻微图像变化更稳定、与决策相关的空间证据。",
    "method": "CLEAR以冻结的预训练分类骨干为基础，采用渐进引导概念感知机制（PGCPM）：先从视觉特征预测局部概念，再将其作为先验引导全局概念推断，最后由概念表示进行分类，同时保留骨干残差特征以减少概念投影造成的信息损失。概念由视觉语言模型辅助生成，经图文相似度和数据集激活频率筛选标注。多视图稳健热图感知（MRHP）比较原图与轻微旋转视图，并通过遮挡局部图块测量分类变化，聚合跨视图一致的重要性作为可视证据。",
    "experiments": "在BreaKHis、Br35H、胸片CXR、BUSI和BACH等医学图像数据集上，与黑盒分类器、PCBM及其他概念瓶颈方法比较准确率、AUC、F1，并做交互策略消融和遮挡分析。ResNet-18下，BreaKHis 40×的准确率/AUC/F1为98.00%/99.54%/98.55%，PCBM为97.33%/99.34%/98.10%；CXR为87.00%/93.80%/86.32%，PCBM为84.00%/92.08%/83.33%。BUSI上CLEAR的MRHP区域遮挡后准确率由93.88%降至88.78%，标准热图区域遮挡后为89.80%，表明所标区域更贴近分类所依赖证据。",
    "contribution": "CLEAR将概念层级关系编码进局部到全局的顺序推理，并让空间解释在轻微视图变化下聚合；多个模态和骨干上的结果显示，相比PCBM通常能缓解概念瓶颈的性能下降，遮挡试验也提供了决策相关性证据。局限是研究主要遵循临床常见的二分类设置，扩展到大规模多类诊断和更复杂概念层级仍待验证；概念生成依赖视觉语言模型辅助，文中证据尚不能等同于临床专家审定或前瞻性临床验证。\n---\nDOI: 10.1016/j.neunet.2026.109892",
    "sample": false,
    "id": "r-1jqekii",
