    "title": "ProCoGuid: Progressive cooperative guidance network for camouflaged object detection",
    "authors": "Fangyan Wang、Ge Jiao、Guowen Yue",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-11-11",
    "contentState": "complete",
