    "link": "https://doi.org/10.1016/j.neunet.2026.109889",
    "direction": "人工智能",
    "summary": "ProCoGuid以无监督类别聚类构造语义先验，并自适应选择结构不确定区域细化特征，再通过多层融合和迭代解码逐步检测伪装目标。",
    "question": "伪装目标与背景在纹理、颜色和结构上高度相似，单靠边缘或手工结构先验难以捕捉隐含类别语义，也容易漏掉细微局部差异。作者试图让类别层面的语义相似性与局部结构线索互补，引导网络由粗到细地定位目标。",
    "method": "ProCoGuid由类别先验建模（CPM）、自适应候选选择（ACS）、多引导特征融合（MFF）和交叉迭代解码器（CID）组成。CPM对训练图像的全局特征作无监督K-means聚类，将聚类中心映射为类别先验图并拼接到输入；ACS根据结构响应的不确定性选取高价值空间位置，裁剪局部区域交由共享编码器细化；MFF以门控融合语义和局部特征，CID在多层间交叉交换并迭代更新分割结果。论文称类别先验不依赖额外人工标注，也不增加推理阶段开销。",
    "experiments": "在CAMO、COD10K和NC4K三个伪装目标检测基准上与16种方法比较，并在息肉分割等下游任务上评估泛化。PVTv2-B2骨干下，ProCoGuid在三套基准的S-measure分别为0.880、0.894、0.897；COD10K上的F-measure为0.829、MAE为0.018。组件消融显示，逐项加入CPM、ACS、MFF和CID后，COD10K的S-measure由基线0.831升至完整模型0.894。模型复杂度为87.273G FLOPs，平均推理速度24.163 FPS。",
    "contribution": "方法将数据内部聚类得到的类别语义先验与不确定区域局部建模结合，并用跨层交互解码逐步细化预测；基准及下游任务结果支持其在多类场景中的有效性。其性能仍有边界：极小、低对比目标以及复杂纹理、模糊边缘场景会出现目标区域不完整或细节遗漏。效率也非同类最优，虽快于若干较重模型，仍低于SINet报告的27.671 FPS；作者提出未来加入深度、红外或文本等线索，并探索轻量化。\n---\nDOI: 10.1016/j.neunet.2026.109889",
    "sample": false,
