    "direction": "人工智能",
    "summary": "SGDA在随机梯度下降中加入归一化梯度差动量，并依据梯度变化调节步长，试图兼顾方向变化信息、更新稳定性和较低额外开销。论文为其在非凸随机优化及凸在线优化设定下给出收敛分析，并与多类优化器进行图像分类比较。",
    "question": "经典动量平滑历史梯度，却可能在梯度方向快速变化时累积不合适的更新；Adam类方法自适应各参数步长，但不直接刻画相邻梯度方向变化。作者关注如何以轻量的一阶信息调整更新幅度，同时避免原始梯度差的尺度敏感性，并在平稳与非平稳任务中保持竞争性。",
    "method": "SGDA计算连续随机梯度的差，并对该差归一化后加入动量修正；步长根据梯度差范数自适应，梯度变化较大时缩小更新，较稳定时允许较大步幅，次级动量系数随训练衰减。算法每步仅需一次随机梯度计算及向量运算，参数量为d时复杂度为O(d)。理论部分在光滑、有界梯度等假设下推导非凸期望驻点界，并在凸在线设定下分析遗憾。",
    "experiments": "实验覆盖USPS、Rotating MNIST、CIFAR-10、CIFAR-100和TieredImageNet，与SGD、SGDM、Adam、RAdam、SGDMD、SGDAMD比较，报告三随机种子结果。CIFAR-10测试准确率SGDA为91.043±0.400%，高于SGDM的90.273%，低于RAdam的92.083%和SGDAMD的92.240%。USPS上SGDA为94.552±0.360%，而SGDAMD为94.685±0.256%；作者还报告SGDA在五项基准均超过SGDMD。",
    "contribution": "论文贡献在于以归一化梯度差提供方向变化信号，并配套自适应更新和收敛分析；多数据集比较显示其优于所测SGDMD，同时在其他基准上多为有竞争力而非全面领先。SGDA每步计算复杂度与常见一阶优化器同阶，但超参数仍需选择；作者也指出在当前实验条件下SGDAMD的准确率通常更高，因此结果不支持其对所有优化器的普遍优越性。\n---\nDOI: 10.1016/j.neunet.2026.109882",
