    "title": "Controlled query evaluation under epistemic policies",
    "authors": "Gianluca Cima、Domenico Lembo、Lorenzo Marconi 等",
    "journal": "Artificial Intelligence",
    "year": "2026",
    "published": "2026-11-12",
    "contentState": "complete",
    "contentNote": "已基于出版社正式版全文完成中文六段式总结",
    "doi": "10.1016/j.artint.2026.104657",
