    "direction": "信息安全",
    "summary": "论文设计并初步评估一款由照护者陪伴的学前儿童游戏，用故事、互动诗歌和小游戏介绍网络安全与数字福祉。",
    "question": "学前儿童已接触网络风险，但单靠限制设备使用难以培养识别风险和求助的能力。现有安全游戏对低龄儿童可能文字过多、概念抽象；作者关注如何把网络钓鱼等概念转成适龄玩法，并让照护者参与学习。",
    "method": "研究采用设计科学方法迭代制作Lucky the Fish原型。游戏围绕丛林故事角色展开，先以互动诗歌介绍主题，再以四道随机问答检查理解并提供即时反馈，最后通过小游戏练习区分安全与不安全情境；照护者可协助解释。研究以儿童观察和专家评审反馈检查可用性、参与度、适龄性及教育内容呈现，并据此修订设计。",
    "experiments": "评估包含两轮儿童观察，第二轮在课堂中有5名儿童参与、持续45分钟，并由教育者引导；另有14名评审者参与专家评估。观察发现儿童会与教育者讨论，不熟悉的概念仍需成人解释。专家认可原型的视觉和互动设计，同时担心低龄儿童的屏幕接触与独立理解能力。这些小样本观察支持原型可参与性，不是长期学习或安全行为改善的证据。",
    "contribution": "论文给出将网络安全内容转成叙事、简单交互和成人协作的原型实践，并识别出低龄儿童无法独立阅读、术语难懂等设计约束。适用定位是教育者和照护者的辅助教学资源；当前样本小、以观察和专家意见为主，没有对照组、长期保持测量或大规模跨地区验证，不能据此断言其提升了儿童长期安全行为。\n---\nDOI: 10.1016/j.cose.2026.105230",
