    "contribution": "把显式边界建模和空间/频域协同融入确定性冷扩散，实验同时考察精度与推理代价。作者指出迭代恢复仍比常规判别式分割耗时；现有验证集中于二维任务，三维、弱监督及多模态场景仍待验证。\n---\nDOI: 10.1016/j.neunet.2026.109908",
