    "title": "Diffusion models with progressive gradient variation for imperceptible and transferable adversarial attack",
    "authors": "Jia-Hua Fan、Heng-Ru Zhang、Fan Min",
    "journal": "Neural Networks",
    "year": "2026",
    "published": "2026-11-12",
    "contentState": "complete",
