    "summary": "论文为随机扰动混沌神经网络设计切换反馈反同步控制器，推导有限/固定时间与能耗界，并用仿真展示速度、能耗和误差权衡。",
    "question": "随机噪声下的反同步需使驱动与响应状态趋于相反，同时兼顾收敛时间、控制能量和瞬态误差；单纯加快收敛可能要求过强输入。作者研究可证明的时间和能耗界及控制参数选择。",
    "method": "在激活函数奇且Lipschitz连续、扩散项满足统一Lipschitz界等假设下，构造按误差范数切换的状态反馈。随机Lyapunov分析给出有限时间充分条件及依赖初态的期望时间上界；加入分区幂次控制项后得到不依赖初态的固定时间界。再推导能耗估计，并以时间、能耗和积分平方误差（ISE）构造加权指标选择增益。",
    "experiments": "随机扰动下的二维混沌网络仿真展示误差轨迹、能量和参数权衡。表2中切换控制器反同步时间0.21 s、能耗4.6；对照为0.15 s、7.3。按表值计算能耗降低约37.0%，但收敛慢0.06 s。正文另称时间缩短23.8%，与表格方向相反，因此不采用该百分比。",
    "contribution": "框架把有限/固定时间条件、能耗估计和ISE权衡纳入统一分析；固定时间理论界不依赖初态。仿真显示切换方案能耗较低但更慢，并非所有指标同时改善。作者指出能耗上界是以分析上界替代状态相关项所得的充分估计，不等于实际能耗；结论也限于给定模型、噪声假设和数值仿真。\n---\nDOI: 10.1016/j.neunet.2026.109905",
