    "summary": "该方法从离线激励数据直接构造未知矩阵混沌神经网络的同步控制条件，并将其用于图像加解密演示。",
    "question": "系统矩阵未知时，传统同步控制依赖模型知识，部分数据驱动方案仍需先建立模型条件或辨识系统。论文研究如何只凭离线采集序列设计事件触发控制器。",
    "method": "先对主从混沌神经网络施加开环激励，采集状态、激活函数和输入序列，再以这些离线数据直接表示未知系统并求解 Lyapunov 矩阵不等式，得到控制增益与事件触发条件；方案不先辨识系统矩阵。文中给出两类数据驱动同步定理，并分析触发阈值和强制采样间隔对通信次数的影响。",
    "experiments": "数值实验以三维 Hopfield 型网络验证同步及触发通信：第一种方案中数据序列数 ι 从13增至999时，最大可行触发参数 ζmax 从0.06增至0.69，5秒内触发次数 α 从147降至65；在第二种方案中，强制间隔 sr 从0增至0.10秒，α 从147降至22（约减少85%）。四维超混沌网络使用1000组离线数据进行同步演示。应用实验对 Baboon 灰度图加密后再解密，恢复图与原图一致；密文信息熵为7.999400（8位灰度理论上限为8），作者也分析了相邻像素相关性。",
    "contribution": "贡献是从有限离线轨迹直接构造未知矩阵神经网络的事件触发同步控制条件，并以定理给出稳定性保证；数据量增加时触发性能趋近已知模型的理想对照。仿真还显示增大触发参数或强制采样间隔可减少通信，但参数过大可能使 LMI 不可行或削弱快速响应。图像加解密及熵值是应用演示，不构成密码学安全证明；结论还以采集数据无噪声等假设为边界。\n---\nDOI: 10.1016/j.neunet.2026.109911",
