    "summary": "论文设计以忆阻器实现完整 Canny 边缘检测流程的电路，并通过电路仿真分析能耗、速度及器件误差影响。",
    "question": "边缘检测是视觉处理前端，但软件实现面临功耗、面积和速度压力。作者希望利用忆阻器非易失、低功耗和高集成特性实现 Canny 全流程，并优化模块互连。",
    "method": "将 Canny 的梯度卷积、幅值计算、双阈值检测和非极大值抑制逐步映射到忆阻器阵列及外围模拟/逻辑电路。3×3卷积核映射为9×2忆阻器阵列，灰度0–255映射为0–0.5 V输入脉冲；针对弱边缘才启用非极大值抑制，以减少无效计算。作者用 SPICE 行为模型仿真，并以 OPA2350UA/2K5 分立器件搭建平台验证模块和完整处理链。",
    "experiments": "电路仿真与硬件平台均展示了从输入像素到梯度幅值输出的处理流程；输入脉冲周期为50 μs。对噪声比例1%、2.5%、5%、10%的分析显示，低于2.5%时输出波动较平缓，达到5%时检测精度明显下降。忆阻器编程误差0.5%、1%、1.5%、3%、5%时，输出准确率分别为99.92%、99.01%、97.43%、94.70%、90.53%。模块功耗表给出权重计算模块静态/动态功耗12.8/22.1 mW、绝对值模块8.4/10.5 mW、梯度幅值模块4.2/6.6 mW；非极大值抑制仅处理弱边缘，作者报告相对遍历全图的传统处理约提速60%。",
    "contribution": "工作实现了覆盖 Canny 全流程的忆阻器边缘检测电路，并通过分立器件平台验证模块和端到端功能；阵列承担卷积计算，弱边缘触发式非极大值抑制减少处理量。定量结果同时揭示容差边界：输入噪声达到5%及编程误差超过3%后精度明显受损。低功耗优势主要来自电路模型分析；原型使用通用运放，论文指出其功耗高于仿真，因此不能把模型功耗直接当作芯片实测能耗。\n---\nDOI: 10.1016/j.neunet.2026.109912",
