    "question": "基于普通图像的 NeRF 在输入存在运动模糊时难以恢复清晰几何与纹理；事件流提供高时间分辨率变化信息，但如何将其与图像的模糊形成过程共同用于重建仍是挑战。",
    "method": "E3NeRF 分别建立模糊图像渲染损失与事件渲染损失，以约束相机运动造成的曝光积分和事件生成过程。训练时利用事件流中的时空模糊线索，在时间模糊与空间模糊相关部分之间分配计算；作者还构建事件引导的真实场景相机位姿估计流程。",
    "experiments": "作者在合成场景、两组自建真实模糊场景、TUM-VIE 与 Ev-DeblurCDAVIS 上比较 E3NeRF 与图像去模糊、事件式及融合式 NeRF。合成场景的七场景平均定量结果列于正文表 III，真实场景的五场景平均结果列于表 IV；论文报告 E3NeRF 在严重抖动和低照度挑战场景中重建质量更稳定（PDF 第10–12页）。在 Ev-DeblurCDAVIS 的全视图设置下，E3NeRF 优于 Ev-DeblurNeRF（PDF 第13页）；具体数值依数据集和视图设置而异。",
    "contribution": "方法将图像模糊物理过程与事件生成机制纳入同一 NeRF 优化，并把事件线索用于训练分配和真实相机位姿估计。效果依赖事件传感器与同步数据质量；真实场景范围和跨设备泛化仍需更广泛验证。\n---\nDOI: 10.1109/tpami.2026.3722771",
