    "contribution": "工作将观测方向不确定性下的敏感性作为平移平均的独立问题，给出条件性分析、充分判据和相应筛选算法。充分条件不等于所有困难场景的必要判据，效果也仍需结合具体相机几何与测量噪声验证。\n---\nDOI: 10.1109/tpami.2026.3722795",
