    "direction": "人工智能",
    "summary": "本文提出在变分自编码器中加入全局尺度潜变量的 EA-VAE，以改善视觉推断中不确定性随图像对比度、退化和分布偏移变化时的校准表现。",
    "question": "标准 VAE 的潜变量假设难以描述自然图像中随整体对比度共同变化的非线性依赖，导致后验不确定性不一定随证据强弱作出合理变化；这会影响模糊输入、分布外样本及下游信息融合的判断。",
    "method": "EA-VAE 在解码生成过程中引入一个正值的乘性尺度变量，用它解释输入整体方差变化，使其余潜变量不必通过相关激活变化重复编码对比度。作者在自然图像设置中采用线性生成模型分析该变量的作用，并在 MNIST、FashionMNIST、ChestMNIST、ImageNet 子集及 NIH-ChestXray14 上使用卷积 VAE 评估；模型与标准 VAE 使用相同潜变量总数和训练条件。",
    "experiments": "自然图像实验显示，标准 VAE 的后验方差没有随对比度增加而呈现预期下降，EA-VAE 则恢复了该变化趋势（PDF 第6页）。在 MNIST 数字渐变实验中，EA-VAE 在 45 组渐变中的 44 组于类别过渡处呈现后验宽度峰值，标准 VAE 仅 14 组（31%）（PDF 第9页）；对 NIH 胸片施加模糊或像素噪声时，EA-VAE 的不确定性随图像质量下降而增加，而标准 VAE 的潜变量不确定性仍近乎恒定（PDF 第8页）。",
    "contribution": "工作将一个简单的生成模型归纳偏置与对比度调制、分布外识别及信息融合中的不确定性联系起来，并报告了与 divisive normalization 相符的识别计算特征。结果支持该结构在所测视觉域中的效用；其证据仍限于论文所用数据集和 VAE 架构，不能据此推断对任意生成模型或临床决策均有效。\n---\nDOI: 10.1109/tpami.2026.3718675 | PDF: [TPAMI_2026_explaining-away-vae_3718675.pdf](papers/TPAMI_2026_explaining-away-vae_3718675.pdf)",
