    "method": "CMAP 利用一致性模型的一步确定性生成，在多个潜向量上联合优化像素与感知一致性，并约束潜向量集合的均值、方差接近模型的先验分布。最终对多个生成结果进行预测投票，以降低单个潜向量偏离数据流形所带来的影响。",
