    "summary": "ADA-CS 在主动域适应中显式估计并优先标注概念偏移显著的目标样本，以改善跨域预测。",
    "question": "不少主动域适应方法主要处理特征边缘分布或类别比例变化，却默认给定特征后的标签条件分布保持稳定；当这一假设不成立时，查询样本可能没有覆盖真正影响迁移的区域。本文关注在源数据不可访问时，如何识别并量化这种概念偏移。",
    "method": "ADA-CS 将标注预算分给既有查询策略和概念偏移选择两部分：先用源模型能量分数估计源/目标边缘密度比，并结合类别平衡权重微调目标模型；再以两模型输出分布的 Jensen–Shannon 散度衡量每个未标注样本的条件分布差异，经局部平滑和聚类选出高差异且多样的样本。",
    "experiments": "研究在 Digits、DomainNet、Office-Home RSUT、Office-31 和超过 220 万条记录的 USAccident 上测试，并与多种主动学习、ADA、SFDA 查询及适应方法组合。Office-Home RSUT 的多数任务和基线在中等预算分配下获得正向准确率提升；在 Office-31 源数据不可用设置及跨州表格任务中也观察到一致改善，概念偏移严重的任务收益更明显（PDF 第8–9、13页）。",
    "contribution": "作者提出可插入不同查询/适应流程的 ADA-CS，并定义 CSS 指标来量化概念偏移，实验还显示适应过程中 CSS 下降。方法依赖第一阶段标注样本能可靠代表目标条件分布；目标池很小、样本选择偏置或把过多预算留给第二阶段时，估计方差和偏差会削弱效果（PDF 第13–14页）。\n---\nDOI: 10.1109/tpami.2026.3724718",
