    "summary": "GFGAD 通过生成带有结构信息的合成异常并过滤冗余邻边，缓解图异常检测中的类别失衡、异常节点结构稀疏与特征伪装。",
    "question": "图异常通常数量少、彼此连接稀疏，还可能通过与正常节点相连而呈现正常特征；常规 GNN 因而难以学到可区分的异常表示。研究关注如何同时补足异常样本与拓扑模式，并减少消息传递中的跨类别噪声。",
    "method": "GFGAD 用生成器从真实异常特征构造合成节点，并学习其与真实异常的连接；图邻居过滤器依据节点嵌入距离逐层剪除不相关边。判别器约束生成样本的真实性，辅助检测器则推动生成结果强化异常分类边界，三者协同训练。",
    "experiments": "作者在七个真实图数据集上以 AUC-ROC 和 AUC-PR 比较多类异常检测基线，并进行模块消融和大图评估。Amazon 上相较 ImGAGN，AUC-ROC 提高 13.64%、AUC-PR 提高 51.23%；在 ogbn-arxiv 上，AUC-PR 比次优方法高 13.36%（PDF 第9、11页）。",
    "contribution": "工作把拓扑感知异常生成与邻边过滤整合进同一检测框架，并报告其可搭配不同 GNN 骨干。局限是生成比例 α 需预先设定，真实异常比例未知时不易确定；作者也指出仍需优化生成效率，以适应超大规模图（PDF 第12页）。\n---\nDOI: 10.1109/tpami.2026.3724665 | PDF: [TPAMI_2026_generate-filter-graph-anomaly-detection_3724665.pdf](papers/TPAMI_2026_generate-filter-graph-anomaly-detection_3724665.pdf)",
