    "summary": "本文提出 PolaFormer++，以极性分解保留线性注意力中的正负交互，并通过按通道学习的尖锐度增强关键 token 的区分能力。",
    "question": "线性注意力虽把计算复杂度降至线性，但常见非负特征映射会丢弃查询与键中的负值关系，且注意力权重可能过于平滑，削弱对显著 token 的选择。",
    "method": "PolaFormer++ 将正负激活拆成双极性流，分别计算同极性和异极性关系，再用极性门控融合。其 PaCS 特征映射为不同通道及极性流学习温度参数，以调节注意力分布尖锐度；论文还分析满足凸性条件的映射与注意力熵下降之间的关系。",
    "experiments": "论文在 ImageNet-1K、COCO、ADE20K、Cityscapes、扩散生成、LLFF 新视角合成及超分辨率等任务评估。ADE20K 上 PolaFormer++-b3 达到 50.5% mIoU，较 EfficientViT-L1 高 1.3 个百分点；Cityscapes 上达到 83.4% mIoU（PDF 第9页）。在线性注意力替换比较中报告最高 5.25 倍速度优势（PDF 第8页），LLFF 平均 PSNR 从 27.25 dB 升至 27.34 dB（PDF 第10页）。",
    "contribution": "工作同时处理正负相似关系缺失和跨通道尖锐度固定的问题，并以理论分析、消融和多任务实验支持设计选择。性能收益是在不同任务各自的模型和训练设置下测得，不能直接视作所有硬件或部署场景中的统一加速；额外通道参数的实际成本仍需结合目标系统衡量。\n---\nDOI: 10.1109/tpami.2026.3723414",
