    "direction": "人工智能",
    "summary": "DeltaGNN 以信息流评分控制图边筛选，并分别建模同配与异配交互，改善长程依赖捕获及深层 GNN 的可扩展性。",
    "question": "消息传递 GNN 在加深时会遭遇过平滑和过挤压，使远距离节点信息难以保留；现有连接重构方法常计算成本高，或难以适应不同同配率、密度和拓扑。本文研究如何以较低开销同时保留短程与长程节点关系。",
    "method": "信息流评分（IFS）根据节点表示变化及其统计量评估连接效用，信息流控制（IFC）在训练中逐层移除低分边，并用效用变化调节过滤强度。DeltaGNN 再将同配与异配边交互分流聚合、合并预测，使局部同类信息与远距离依赖都能参与表示。",
    "experiments": "论文在十个数据集上评估；六个不同同配率数据集的结果显示，DeltaGNN 在其中四个超过所比较方法，平均准确率提高 1.23%，且 IFC 相比最慢变体平均减少每轮训练时间 30.61%。稠密 MedMNIST 图上相较基线平均准确率提高 0.92%，相关基线出现超时或显存不足（PDF 第9、12页）。",
    "contribution": "IFS/IFC 与双路径结构为低计算开销的深层图学习提供了一种可扩展方案，实验覆盖不同规模、密度和同配率。仍需谨慎看待拓扑压缩过程对下游性能的影响：作者指出若干连接度量在异配图凝缩中的表现差异是否会影响模型尚待实验验证，且部分稠密图比较受硬件限制（PDF 第12页）。\n---\nDOI: 10.1109/tpami.2026.3725398",
