    "question": "单目光流方法已较成熟，但光学扩张常被当作光流的派生量，缺少针对尺度变化的独立建模；纹理与局部尺度线索若不能互补，也会限制动态场景下的运动估计。本文关注如何让两类线索共同支持像素级运动感知。",
