    "contribution": "核心贡献是把光学扩张作为具有独立尺度特征流的稠密预测目标，并设计纹理—尺度交互与循环细化。局部标量尺度不能完整表示旋转、剪切、各向异性形变或遮挡导致的局部映射变化；作者也指出特征融合带来计算负担（PDF 第11页）。\n---\nDOI: 10.1109/tpami.2026.3725402",
