    "contribution": "工作给出了闭合路径增强超图结构辨别能力的核方法与神经网络实现，并以理论和实验展示其优势。证据主要来自特定合成结构、关系网络和构造的蛋白质超图，结果不能直接等同于所有真实超图任务；作者还指出团展开导致的可区分现象可能是投影失真造成的假阳性，不应据此评价表达能力（PDF 第15页）。\n---\nDOI: 10.1109/tpami.2026.3724944",
