    "question": "过挤压描述远距离节点信息在有限维消息传递中被压缩、使长程依赖难以学习的现象，但不同研究采用的定义、指标和实验设置并不统一。综述旨在梳理这些差异，并厘清过挤压与过平滑及模型表达能力的联系。",
    "method": "文章按空间重连、谱重连和隐式重连归纳缓解策略，讨论曲率、有效电阻、谱量及敏感度等解释框架，并整理合成图、经典图和长程依赖基准及计算复杂度。作者进一步比较不同定义和理论边界之间的对应关系，而非提出单一新模型。",
    "experiments": "本文是综述，没有报告统一的新模型实验或自有基准结果；其经验性证据来自对既有工作的归纳，涵盖环形源—目标传递任务、Cora/CiteSeer/PubMed、长程图基准以及用于可扩展性测试的随机图。综述指出当前尚无直接且统一的过挤压实证度量，且实验往往难以与过平滑效应分离（PDF 第15–17页）。",
    "contribution": "文章提供了方法分类、基准地图以及理论联系的集中梳理，并将过挤压与过平滑之间可能存在的权衡作为重要议题。局限/开放问题包括定义与界限尚未统一、最佳网络深度难确定、直接量化指标缺失，以及超图场景中的机制和指标仍缺少系统研究（PDF 第16–17页）。\n---\nDOI: 10.1109/tpami.2026.3725957",
