    "summary": "CrossGuard 研究跨模态检索中的隐私保护与检索效用，提出三值稀疏哈希框架，将图像和文本映射为含正、负及不确定状态的紧凑码。其目标是在外包检索时减少敏感表示暴露，同时保持跨模态相似样本的排序能力。论文以公开基准评估检索精度、码长和隐私相关指标，讨论不同设置下的效用—保护折衷。",
    "question": "实值深度跨模态检索可取得较高精度，但模型训练外包和云端查询可能暴露训练信息或查询语义；二值哈希虽紧凑，却可能因量化损失影响相似度排序。论文关注稀疏三值编码能否兼顾检索质量、通信存储成本和隐私目标。",
    "method": "模型学习图像与文本的跨模态稀疏哈希表示，以三值码表达可靠匹配与不确定维度，并通过联合目标对齐模态语义和约束编码稀疏性。实验分别评估检索任务与隐私属性。",
