    "contribution": "方法把视角顺序对称性转化为成对预测机制，降低递归深度并改善背面视图一致性。单图输入仍无法恢复被遮挡且缺乏语义/几何线索的细节，背面输入时性能会明显下降；自回归生成也比并行视图生成更慢，文中运行时间比较并非严格同硬件对照（PDF 第10–11页）。\n---\nDOI: 10.1109/tpami.2026.3726806",
