    "direction": "人工智能",
    "summary": "论文提出边界感知数据增强 BADA，以改善离线强化学习对训练数据过拟合、面对状态分布变化时泛化和鲁棒性较弱的问题。方法依据邻近状态构造插值边界，限制合成状态落在局部邻域内，避免普通增强把样本推离原始数据分布。作者从转移函数误差分析出发，在玩具环境及离线控制基准中评估策略收益。",
    "question": "离线强化学习不能通过在线交互纠正训练分布之外的估值偏差；直接插值或扰动状态可能改变低层物理信号的局部结构，生成偏离数据支持范围的样本。研究的问题是怎样在扩充有限数据多样性的同时保留邻域平滑性，提升分布内泛化和部署鲁棒性。",
    "method": "作者分析随机回合插值下转移函数误差与状态距离的关系，据此利用时间相邻状态或空间最近邻构造边界，在边界内生成合成数据。时间边界查询开销为常数级，空间邻域搜索随样本规模增长，论文使用近邻索引加速；增强数据用于离线策略训练。",
    "experiments": "玩具环境的可视化比较显示，BADA/SBADA 的合成状态保持在邻近样本边界内；后续离线强化学习基准比较策略回报、分布内泛化和扰动下鲁棒性，报告相对常用增强及正则基线总体改善，但效果随环境和数据质量变化（PDF 第1–3页、第8–12页）。",
    "contribution": "工作以邻域边界约束增强样本，并把转移误差分析与离线策略评估相联系。证据来自仿真基准而非真实机器人或部署；最近邻搜索和边界质量依赖数据密度，低覆盖区域仍难可靠增强，且优势不能推及未测环境或任意分布偏移。\n---\nDOI: 10.1109/tkde.2026.3729748",
