    "doi": "10.1109/tkde.2026.3729874",
    "arxiv": "",
    "pdf": "",
    "link": "https://doi.org/10.1109/tkde.2026.3729874",
    "direction": "人工智能",
    "summary": "PBC 是面向半结构化数据的模式压缩方法，针对日志、JSON、XML 等记录内部反复出现的结构模板，在记录粒度去重模板并保存变化值。这样既利用记录间结构冗余，也让单条记录能够独立定位，试图缓解传统块压缩率高但随机访问慢、格式专用压缩适用面窄的矛盾。作者在真实与基准数据上评测，并集成到生产数据库系统。",
    "question": "通用压缩通常按块处理，随机读取单条记录时需要解压较大区域；专用压缩又常依赖已知 schema 或格式规则，难适应来源多样的半结构化数据。论文提出的核心问题是能否从记录中自动识别重复结构，同时保留快速随机访问能力和有竞争力的吞吐。",
    "method": "PBC 以记录为单位识别重复结构模式，将共享模板与各记录中的实际值分开编码，并维护支持记录级定位的表示。相比块级通用压缩，它把结构冗余作为压缩对象；作者进一步把方法接入数据库系统，测量压缩率、随机访问性能和吞吐，而非只报告离线压缩率。",
    "experiments": "真实及基准数据集上，论文报告相较先进方法压缩率最高改善50%，同时保持较好的随机访问性能和有竞争力的吞吐；数据库集成实验也显示压缩与访问指标得到改善（PDF 第1页、第6–10页）。“最高”是特定数据集和配置的结果，不代表每类记录均提升50%。",
