    "method": "GGTSM 以混合 GCN–GAT 教师学习实体和关系表示，并依据关系与节点注意力自适应加权蒸馏信号。子图模块整合局部邻接和批次结构，为新实体建立粗表示，再在教师输出指导下细化学生表示；测试协议专门构造训练未见实体的链接预测任务。",
    "experiments": "FB15k-237、WN18RR、NELL-995 三个数据集上，论文报告相对基线平均 MRR 提升0.15，Hits@1、Hits@3、Hits@10 分别平均提升18%、41%、63%（PDF 第1页、第5–10页）。参数量约为2.38M、4.99M、6.23M；论文指出部分子图缓存等非训练结构未计入，且训练时间高于部分基线（PDF 第12页）。",
