    "summary": "论文定义用户指定规模 k 的空间共址模式挖掘任务，并提出 k-pattern-Miner。传统逐级挖掘可利用向下闭包剪枝，而直接寻找指定规模时失去这一性质；新方法以实例着色图和 (k−1) 度约束构建表示，逐轮剔除不可能参与目标模式的特征与空间实例，降低后续验证成本。",
    "question": "现有空间共址挖掘多生成所有规模的模式，对只关心固定规模的应用造成候选和存储开销；直接定规模又无法沿用经典向下闭包剪枝。研究要解决的是如何在不枚举大量中间规模模式的情况下，仍能有效缩小候选实例空间并适配不同流行度指标。",
    "method": "k-pattern-Miner 用 IC+(k−1)deg 表示空间实例及其邻接关系，结合实例着色与度约束执行两阶段剪枝，再验证 k 元模式。作者还将框架扩展至 InterPCI 流行度度量，并与可适配的逐级方法、无连接挖掘和极大团方法比较运行时间及规模扩展性。",
    "experiments": "真实北京 POI 数据和合成数据实验显示，多个 k 值下方法运行时间比对照低数个数量级；对 InterPCI 也持续快于 CS-HBS。剪枝策略一的最高剔除率为70.8%，策略二最高约25%；合成数据中实例数从500增至2000时仍保持最低运行时间，而部分对照在更大特征规模下无法完成（PDF 第1页、第13–15页）。",
    "contribution": "贡献是针对定规模共址挖掘设计不依赖逐级向下闭包的图式剪枝，并验证其在真实、合成数据及另一流行度指标上的效率。结论主要是运行时间和可扩展性，不证明挖出的模式具有因果或应用价值；测试数据与阈值配置有限，稠密空间关系和不同分布下的内存成本仍需进一步评估。\n---\nDOI: 10.1109/tkde.2026.3730036",
