    "summary": "只看混淆矩阵和准确率会把概率输出压成单一类别，因此模型即使信心很弱，只要最大概率类别不变，硬标签指标也可能显得同样优秀。本文提出以概率质量混淆矩阵 CM⋆ 直接评估分类器，并把预测概率分解为决断部分与非首位类别上的残余分散部分。",
    "question": "概率分类器的预测质量如何在保留类别判断的同时，呈现不确定性及其分布，而非仅汇报 argmax 决策的正确率？",
    "method": "作者定义概率质量混淆矩阵 CM⋆，再构造无阈值的决断与残余分量，以分别描述首位类别集中度和其余类别间的概率分配；据此建立概率准确率及多类别分类表现曲线等评价量，并与传统硬标签指标互补。",
    "experiments": "在 27 个 UCI 数据集上比较指标，并以随机森林为基线：平均准确率为 0.87，概率准确率 Acc⋆ 为 0.77，多类别分类表现曲线下面积为 0.71。概率确定性与名义指标和概率指标之间较小的差距呈单调关联；在保序校准的多项逻辑回归上也观察到这一趋势（PDF 第 1 页）。研究未证明这些概率指标可单独衡量校准质量，作者主张与概率质量诊断共同解释。",
