    "method": "DADO 由属性生成器和评分器构成双代理流程，以评分反馈约束生成样本的分布；另用多层提示、排除机制及少样本选择增加词汇变化。作者在电商、社交媒体和情感分析场景评估分布对齐、多样性、人评质量及增强后的分类损失。",
    "experiments": "跨领域实验报告词汇多样性最高达到对照的 1.5 倍；用合成数据增强后，交叉熵损失降低 5.6%–35.3%，人工评估也支持生成质量改善（PDF 第 1 页）。不同任务上的增益幅度不一，结论受数据集、生成模型和提示配置限制。",
    "contribution": "贡献是把类别分布约束和多样化生成纳入同一生成流程，并用下游损失而非仅生成文本指标验证效用。局限在于实验场景和模型设定有限，合成数据质量与收益可能随目标领域及生成器改变。\n---\nDOI: 10.1109/tkde.2026.3736076",
