    "method": "作者系统梳理不同任务和方法谱系，并在多个公开数据集上复现实验比较；同时分析文献中同模型同数据集结果的离散度及微调学习率等因素的影响。综述据此归纳数据量、微调与上下文少样本学习对性能的关系。",
    "experiments": "定量比较发现，图方法在多数评测数据集上未超过微调 Transformer；有足够训练数据时，微调语言模型通常胜过 decoder-only 生成模型的少样本上下文学习，而所需数据量依任务而异。文献中同一 BERT 及相同数据划分的准确率差异最高约 13 个百分点，学习率等设置会影响结论（PDF 第 3 页）。综述覆盖范围、语言及生成模型训练数据泄漏均限制外推。",
    "contribution": "贡献是把多个分类任务和方法类别放入共同评测，并强调强基线与调参规范对判断真实进步的重要性。作者建议数据充足时微调语言模型，数据有限时考虑冻结生成模型的少样本方案；结果不应被视为对未覆盖语言和数据集的普遍定论。\n---\nDOI: 10.1109/tkde.2026.3735248 | PDF: [TKDE_2026_text-classification-comparative-review_3735248.pdf](papers/TKDE_2026_text-classification-comparative-review_3735248.pdf)",
