    "experiments": "论文比较了 GIFT-Eval 的 MASE 与 CRPS，以及 FEV 的平均胜率与技能分数。FEV 涵盖 7 个领域的 100 项任务，结果表明自动试验和集成可以改善所测基础模型的预测表现（PDF 第 7–9 页）。",
    "contribution": "贡献是把模型选择、上下文长度搜索、预测仲裁和结果解释组织为训练免费的闭环代理，兼顾自动化与可读性。局限在于目前证据集中于特定基准和离线预测流程，其他时间序列任务及在线场景尚待验证。\n---\nDOI: 10.1109/tkde.2026.3736409",
