    "question": "传统谱正则化的滤波通常仅依赖奇异值，难以针对各观测系数差异调整抑噪；学习型重建则常受固定网格表示限制，且函数空间架构本身不能保证噪声趋零时的收敛。作者因而问：系数依赖的学习滤波能否获得经典收敛阶，并在相容离散化之间保持一致？",
    "method": "SC-Net 将共享神经网络作用于保留模态，以观测系数和奇异值输出有界阻尼。理论上，在 Hilbert 尺度源条件、代数奇异值衰减、网络族一致有界及逼近恒等条件下证明经典截断谱收敛阶；另在稳定投影和相容谱系假设下证明固定重建规则的离散一致性。",
    "experiments": "一维合成实验的误差标度与理论阶一致；加入观测系数条件后，相对仅用奇异值的消融平均误差降低12.5%。在固定算子基准中，可实现方法里差异原理锚定 FNO-1D 误差最低；二维高斯去模糊测试中，Tikhonov 锚定 SC-Net 在所测模糊宽度及留出宽度上优于同信息量算子条件 FNO。固定模态跨分辨率差异下降，但其网格相关条件化限制了与定理的直接对照（PDF 第1页、第6–10页）。",
    "contribution": "工作把可学习的逐系数滤波与谱正则化理论联系起来，给出不要求噪声一致 Lipschitz 常数的收敛保证，并分析离散一致性。实验覆盖不同噪声分布和模糊宽度，但二维比较不能单独识别算子分布变化的敏感性；跨分辨率实验也不是定理条件下的固定规则验证。\n---\nDOI: 10.1016/j.neunet.2026.109794",
