    "method": "网络耦合参数用凸多面体时变模型描述，传输采用受比特率限制的编码解码机制，执行器故障以随机模型表示。作者构造簇同步反馈控制器，通过 Lyapunov 与线性矩阵不等式推导均方指数最终有界的充分条件，再以遗传算法式的 PGA 搜索比特率分配并协同求解控制增益。",
