    "contribution": "论文将时变耦合、随机执行器故障和受限数字通信统一纳入簇同步设计，并把资源分配与控制器联合考虑。证据来自单一数值网络而非硬件或真实通信实验；结论依赖模型假设和充分条件，作者指出一般有向拓扑以及更强定时保证仍待研究。\n---\nDOI: 10.1016/j.neunet.2026.109850",
