    "contribution": "提供可插拔的局部二阶特征模块，控制完整二次建模的成本。仍有参数、采样和计算额外开销；本文二维分割结果不自动证明三维体积分割、真实临床诊断或所有器官均有收益。\n---\nDOI: 10.1016/j.neunet.2026.109808 | PDF: [NN_2026_STKQC.pdf](papers/NN_2026_STKQC.pdf)",
