    "method": "RDGCN设置语义、标签上下文和拓扑编码器，以标签上下文正则及拓扑重构约束各视角，再进行自适应节点级融合。这样可保留节点自身信息，同时选择性吸收邻域与结构信号。",
    "experiments": "在九个同配及异配节点分类基准上比较。Squirrel准确率73.52%，对比M2M-GNN的63.60%提高9.92个百分点；Chameleon为76.71%，但Texas和PubMed并非最优，不能概括为所有数据集均领先（PDF第7页表4）。",
    "contribution": "用可区分的表征视角统一处理不同图性质，消融支持编码器与正则的作用。拓扑重构需要节点间成对内积，大图内存与计算成本仍是限制；既有节点分类结果不自动证明其他任务或更大图上的收益。\n---\nDOI: 10.1016/j.neunet.2026.109799 | PDF: [NN_2026_RDGCN.pdf](papers/NN_2026_RDGCN.pdf)",
