    "experiments": "在CIFAR-100、ImageNet-1K和WMT14翻译任务上评估。ImageNet-1K的MobileNet-V3实验中，Mish的Top-1由72.36%升至72.59%，GELU由72.64%升至72.73%；但PReLU从70.55%降至41.58%，说明收益高度依赖基础激活（PDF第12页表6）。",
