    "experiments": "联合推断主要改善稳定性，未在所有任务和生物情境下一致提高预测表现。造血KPNN剪枝后重新加入被排除的100个高信息量基因，准确率从0.576升至0.906、macro F1从0.424升至0.848，边数也从267增至11,924；先验网络仅保留20%时，iMAT各次运行均未产生活跃反应（PDF第6页）。这些指标不是对真实因果相互作用的独立验证。",
