    "contribution": "贡献是用已有硬件原语组织可更新、可强制触发的保护与恢复链。它不保证阻止全部内核内存攻击；物理完整性与可信基础设施是前提，侧信道等不在保障范围。恢复时屏蔽中断，因而不适合严格硬实时控制，也尚未验证大规模设备群协同恢复（PDF第14—15页）。\n---\nDOI: 10.1016/j.cose.2026.105137 | PDF: [COSE_2026_HardwareAnchoredAssurance.pdf](papers/COSE_2026_HardwareAnchoredAssurance.pdf)",
