    "question": "排队系统等模拟器可以生成数据，却往往无法直接计算似然。若用似然及其导数的随机估计量作比值来估计得分函数，分母噪声会引入偏差，使常规单时间尺度更新不稳定、增加模拟样本也代价较高（PDF第1—4页）。",
    "method": "用快时间尺度递推跟踪参数得分，慢时间尺度更新待估参数，避免显式随机除法。对后验推断，结合外层样本平均近似与并行内层跟踪器来优化证据下界；并扩展为似然网络和后验网络以不同频率训练的方案（PDF第8—11、25—26页）。",
