    "contribution": "贡献是将去比值偏差的递推与嵌套推断统一，并给出收敛性、渐近分布及速率分析。理论依赖平滑性、估计器矩条件、似然正下界和步长分离等假设；神经网络扩展还需似然逼近偏差递减。有限仿真结果不能保证任意复杂模型全局最优，也不意味着消除所有近似误差（PDF第4、12—26页）。\n---\nDOI: 10.1007/s10994-026-07175-y | PDF: [ML_2026_NestedStochasticApproximation.pdf](papers/ML_2026_NestedStochasticApproximation.pdf)",
