    "experiments": "本文没有提出新模型或开展统一的新训练对比，成果是分类与策略对照、代表性基准汇总及文献证据分析。作者指出现有评估偏重合成扰动，真实分布变化、复合扰动、跨训练与部署阶段以及行为指标覆盖仍不足；不能把所引研究的结果当成本篇独立实验。",
    "contribution": "贡献是把扰动揭示脆弱性与增强鲁棒性的双重作用放入统一框架，并比较数字和物理场景下的攻击、防御与成本。主体集中于图像分类，向其他任务和模态推广仍有限；基准真实性、多扰动联合评估及大规模计算成本是开放问题。\n---\nDOI: 10.1109/tkde.2026.3709786 | PDF: [TKDE_2026_DataCentricChallengesTechniques.pdf](papers/TKDE_2026_DataCentricChallengesTechniques.pdf)",
