    "direction": "人工智能",
    "summary": "这项实证研究表明，因果效应估计的结果不仅取决于估计器，还强烈受超参数与调参指标影响；普通预测误差较小，并不保证因果效应估计更准确。",
    "question": "观察数据无法同时展示同一对象接受与不接受干预的结果，因此真实因果误差通常不可直接测量。研究者只能用可观测指标选模型，而不同论文的调参方式又不一致，容易将调参优势误认成估计方法本身的优势（PDF第2—3、10—13页）。",
    "method": "在IHDP、Jobs、Twins和News四个基准上组合7类因果估计器、9类基础学习器及多组超参数，比较均方误差、插件估计、匹配和R-Score等选择指标。常规选择在验证数据上进行，最终效果在独立测试集评估；另借助基准中的反事实真值构造Oracle，用于衡量理想调参潜力，而非现实可用的选择方法（PDF第8—9、13—17页）。",
    "experiments": "图2汇总显示，使用理想指标选择最佳超参数后，达到文献既有领先水平的比例，在平均效应任务上由约0.65升至0.81，在个体化效应任务上由约0.50升至0.57。可观测指标之间表现和稳定性差异明显，未找到普遍最优指标；这些比例是跨基准与模型组合的汇总，不是效应误差降低比例，也不是现实数据上的可保证收益（PDF第18—20页，图2—4）。",
    "contribution": "贡献是拆开估计器、基础学习器、超参数与评价指标的影响，提示因果基准比较需要统一调参条件。结论依赖无未测混杂等识别假设和有限搜索空间，不能解决隐藏混杂。部分基准采用模拟结果，跨数据集合并也掩盖差异；附录直接在测试集选择的替代Oracle仅供诊断，不应作为无偏泛化评估或部署流程（PDF第21—25、28—32页）。\n---\nDOI: 10.1007/s10994-026-07140-9 · PDF: [ML_2026_CausalEffectHyperparameterTuning.pdf](papers/ML_2026_CausalEffectHyperparameterTuning.pdf)",
