    "summary": "论文将工业物联网入侵检测改为可解释的攻击阶段识别，并比较特征模型、图模型与融合模型；结果显示模型优劣依赖数据集，融合并不必然更好。",
    "question": "传统入侵检测的单一攻击标签难以表达入侵所处阶段，也容易忽略通信资产间的关联。作者希望利用图关系辅助分诊，同时严格区分“识别已发生的阶段”和“提前预测后续破坏”，避免把后见信息当作预警能力（PDF第2—3页）。",
    "method": "以ATT&CK为启发，将网络流量映射为正常、初始访问与发现、横向移动/执行/持久化、影响四类。ToN-IoT按资产和时间窗构图，Edge-IIoTset因时间戳不足采用记录级表示；比较随机森林、GCN、GAT等模型及概率融合，按资产隔离数据划分并仅用训练数据拟合预处理。另提出只使用截止时刻前证据的双流GRU预测方案（PDF第6—19页）。",
    "experiments": "三次随机种子实验中，ToN-IoT的GAT取得最高Macro-F1，为0.687±0.041，RF–GCN堆叠仅0.395±0.067；Edge-IIoTset则以随机森林最佳，为0.6146±0.0027。ToN-IoT虽有21,313个候选预测实例，但仅5个正例且全在训练集，验证和测试均无正例，因此作者未报告留出集上的预测性能（PDF第20—22页，表14、16）。",
    "contribution": "贡献是给出阶段化检测、身份隔离评估及数据泄漏控制的可复现框架，并如实报告融合失效与预测验证不可行。阶段标签只是粗粒度操作抽象，不是完整ATT&CK真值；实验仅使用网络遥测和受控测试床，尚不能证明完整供应链、多模态或在线冷启动效果，预测方案也仍待有效纵向数据验证（PDF第6—7、21—23页）。\n---\nDOI: 10.1007/s10207-026-01340-z · PDF: [IJIS_2026_IIoTStageAwareGraphDetection.pdf](papers/IJIS_2026_IIoTStageAwareGraphDetection.pdf)",
