    "question": "时间序列异常检测常以基线比较衡量进展，但在测试集上选择阈值、按真实异常区间修正预测，以及拼接本不连续的独立序列，都可能扭曲结果。即使更换数据集或评价指标，若预处理和基线实现不透明，仍难判断性能差异来自模型还是实验流程（PDF第2、7—10页）。",
