    "summary": "论文指出 CART 的贪心纯度增益在某些非零误差情形下可能为零，令一致性分析受阻；作者以 Influence 分裂准则和网格估计构造 GridCART，并将其扩展为随机森林与梯度提升树。",
    "question": "常见 CART 依据子节点平均标签计算纯度增益，可能遇到任何候选切分都没有增益、但分类误差仍非零的情形。随机树已有一致性理论，而依赖标签贪心分裂的树通常需要对目标函数作较强结构假设；本文试图在不假定目标可加的前提下分析这类学习器。",
    "method": "InfCART 用坐标方向上的条件 Influence 衡量切分效果：在乘积分布下，只要误差非零就存在正增益，但该准则依赖未知总体分布。GridCART 以直方图估计各特征分布和目标函数，再在规则网格上搜索切分，使总体准则可由样本近似。GridForest 通过特征抽样、子采样和随机平移网格鼓励树间差异；GridGBDT 则将残差直方图化，理论分析聚焦平方损失及各轮共用的未平移网格。",
    "experiments": "作者在 20 个 OpenML 二分类数据集上比较方法，使用十组配对随机种子并以 macro-F1 评估。GridCART 平均为 0.811，CART 为 0.808；GridForest 平均为 0.833，随机森林为 0.831；GridGBDT 平均为 0.831，常规 GBDT 为 0.823。合成数据上，XOR 任务的测试准确率为 94.8% 对 83.1%，运行时间为 0.7 秒对 138.3 秒（GridCART 对 CART）。作者报告整体表现可比，但这些实测优势不是一致性定理所保证的集成增益。",
    "contribution": "论文为贪心、标签依赖的树及其森林和平方损失提升变体建立一致性率，并给出网格平移兼顾多样性的构造。理论依赖特征乘积分布；真实数据实验改用联合直方图，因而不落在该理论假设覆盖范围内。GridForest 的定理分析无放回子采样变体，且没有证明集成优于单树；GridGBDT 的一致性证明只覆盖共同未平移网格，随机平移下的证明仍待解决。\n---\nDOI: 10.1007/s10994-026-07165-0",
