    "direction": "信息安全",
    "summary": "论文提出 ICRIM（Integrated Cyber Resilience Indicators Model），用技术、组织、社会心理与关系三个相互关联的领域整理网络韧性指标，帮助区分“要观察的韧性属性”和“实际采用的测量方法”。它是供后续操作化与检验使用的概念框架，并非已验证的评估量表。",
    "question": "网络韧性研究横跨工程、组织治理和人的行为，但“指标、度量、能力、目标”等术语常被混用，不同研究采用的证据和分析层级也难以直接比较。只看系统性能，可能忽略治理、人员协作与恢复能力；把这些内容简单合并成一个分数，又会掩盖它们测量方式的差异。作者希望先建立可追溯的概念结构，为情境化测量打基础。",
    "method": "作者对 2011—2024 年间筛选出的 33 篇文献开展结构化、理论引导的概念综合，而非穷尽式系统综述或新数据实验。检索涵盖 Scopus、Google Scholar、相关机构网站及参考文献追溯；逐篇提取指标类型、操作化形式、理论依据、验证或应用证据，再以预先设定的三领域框架进行迭代归类。技术类研究常用数学、时间、结构或概率度量；组织类常见成熟度标准、问卷、专家判断或任务导向模型；社会心理与关系类指标多嵌入更广的组织或人员评估中。",
    "experiments": "本文没有提出实证实验或性能提升结果。综合发现是，三类指标的操作化程度不均，且不少指标跨越领域：例如系统功能保持属于技术结果，其重要性仍取决于组织定义的任务需求；培训安排属组织能力，培训后意识与行为变化则涉及社会心理层面。ICRIM据此以非层级结构呈现指标家族及领域间关系，不规定通用指标、权重、阈值或评分法（第 9—10、15 页）。",
    "contribution": "主要贡献是明确区分概念指标与操作度量，并把技术表现、组织能力和社会关系放进同一分析框架，同时保留其差异。局限来自研究设计：文献库由相关性筛选形成，不代表全领域穷尽覆盖；主要提取与分类由第一作者完成，未进行独立双人编码或一致性检验；三领域也只是理论引导的初始分类。ICRIM尚未在真实组织、仿真或纵向研究中验证，实际可用性与测量效度仍待经验研究确定。\n---\nDOI: 10.1007/s10207-026-01341-y",
