    "summary": "研究构造多种提示泄漏攻击，比较 LLM Guard、Vigil 与 Rebuff 的提示注入检测器，分析不同检测机制在召回攻击和控制误报之间的取舍，并展示 canary 检查与模型分类器实现中的薄弱点。",
    "question": "提示泄漏会诱使应用中的模型暴露系统指令，单纯拦截明显触发词容易被上下文忽略、上下文操纵、前缀注入或字符混淆绕过。尽管开源检测工具已被用于实际应用，作者指出其对提示泄漏的实测比较仍不足，尤其需要同时观察攻击漏检与正常请求误报，而非只看单一准确率。",
    "method": "作者以两个种子提示生成并筛选攻击文本，再组合朴素泄漏、忽略上下文、操纵上下文、前缀注入和 leet 混淆等技术；每类只保留经模型测试确认有效的样本。数据集含 11,000 条恶意提示和 1,000 条正常文档问答请求。研究逐项测试 LLM Guard、Vigil、Rebuff 的 Transformer、规则、向量库、二级模型、相似度及 canary 检测器，并按各系统策略计算整体表现；另将攻击样本用于 GPT-4o 与 Claude 3.5 Sonnet 的泄漏测试。",
    "experiments": "Transformer 检测器总体能识别超过 99% 的恶意样本，但伴随可见误报。表 3 中，LLM Guard Full 模式召回率为 0.999、误报率为 0.127；Vigil 阈值设为 0.98 时分别为 0.986 和 0.050，阈值设为 0.999 时为 0.968 和 0.014（第 9 页）。按整体检测策略比较，Vigil 在误报控制上表现最好，Rebuff 召回更高且误报代价较小；LLM Guard 检出全部攻击样本，但误报率最高。作者还发现 Rebuff 的二级模型检测可被提示模板格式利用而绕过，并通过调整系统提示中的 canary 指令改进其 canary 检查。",
    "contribution": "研究提供了覆盖多种攻击组合的提示泄漏测试集，比较了检测器内部机制及整套策略，并给出 canary 与二级模型扫描器的具体改进方向。结论受合成数据设计约束：攻击样本来自有限种子和既有技术，正常样本为特定文档问答应用中的请求；因此指标说明这些工具在该测试集与实现版本上的表现，不能直接推断生产环境中的攻击发生率或跨应用效能。作者也指出，后续需纳入更多真实攻击技术并重新校准应用相关的阈值。\n---\nDOI: 10.1007/s10207-026-01338-7",
