    "summary": "作者为高能前沿中稠密、重叠且来自异构子探测器的中微子事件构建稀疏多模态编码器，以自监督预训练学习可复用表征，并评估其多任务收益、低标签效率和跨探测器迁移。",
    "question": "FASERCAL 概念探测器的事件含大量重叠的粒子簇射和轨迹，传统重建困难；从头监督训练又受稀缺标签限制，而且不同物理分析需要分类与回归等多个任务。作者将“foundation-style”限定为可跨任务复用并经迁移测试的表征，不声称已经得到通用探测器基础模型。",
    "method": "模型用稀疏 3D 卷积处理 3DCAL 与 AHCAL 体素，经模块内注意力和 Perceiver-IO 融合 ECAL 能量矩阵及 μ 子谱仪信息。预训练先以 75% 遮蔽率重建体素占据与电荷，再继续训练 ghost、相互作用层级和粒子类别等关系目标；随后联合微调中微子味道、粲夸克类别、动量及顶点任务。比较随机初始化、仅 MAE 和 MAE 加关系目标三种初始化。",
    "experiments": "在 FASERCAL 模拟测试集（122,638 个事件）上，ντ→had 的 AUC 从 scratch 的 0.902 提高到 MAE 的 0.941、MAE+Rel 的 0.944。约 1,000 个有标签事件时，味道分类 macro-AUROC 分别为 0.736、0.790、0.818；MAE+Rel 超过用约 10,000 个标签训练的 scratch（0.807）。迁移至 PILArNet 多粒子分类时，准确率/AUROC 从 scratch 的 0.9333/0.922 升至 0.9662/0.951。匹配 GENIE 与 NuWro 的测试中，MAE+Rel 味道 AUROC 仅从 0.932 变为 0.928，但粲分类从 0.864 降至 0.721。",
    "contribution": "工作展示同一稀疏编码器可支持异构探测器输入、多种物理任务及跨域迁移，并量化自监督预训练降低标签需求的效果。证据来自模拟，关系目标依赖模拟真值；替代生成器测试也显示粲标记对生成器敏感。研究只检验了特定匹配生成器和整体量能刻度偏移，不能替代通量、子探测器响应等系统误差研究或实验数据校准；因此结果支持的是有边界的可迁移表征，而非生成器无关或已完成的通用模型。\n---\nDOI: 10.1038/s42256-026-01309-6",
