    "title": "SURGE: Structural Perturbation Response Field Guided Residual Distillation for Graph Unlearning",
    "authors": "Chaofan Shen、Mingyu Wang、Jing Zhang",
    "journal": "Machine Learning",
    "year": "2026",
    "published": "2026-10-07",
    "contentState": "complete",
