    "summary": "这篇系统综述综合 94 项同行评审研究，梳理基础模型的安全弱点、红队评估、缓解措施与评价实践。其核心结论是，模型安全风险会跨提示、模型、数据和部署层相互作用，而现有测试与指标不统一，导致防御效果难以横向比较。",
    "question": "大语言模型正进入医疗、网络安全、软件工程和基础设施等高影响场景，提示注入、越狱、幻觉及多模态操纵可能带来隐私、完整性和可靠性问题。单一攻击或静态基准不足以代表实际系统风险；不同研究的威胁模型、攻击预算、数据集、指标及评判方式又不一致，使“某防御更有效”的跨研究结论容易失真。",
    "method": "作者按 Kitchenham 系统综述指南开展研究，并以 PRISMA 2020 辅助报告筛选流程；检索范围为 2021 年 1 月至 2026 年 7 月，结合数据库检索、反向引文追溯和指定会议筛查。382 条数据库记录去重后为 267 条，标题摘要筛选后 174 篇进入全文评估；合并补充检索后 101 篇进入质量评估，排除 7 篇低于质量门槛的研究，最终综合 94 篇。作者进行多标签编码与叙述综合；由于模型、任务和评价协议差异大，未做元分析（第 5—9 页）。",
    "experiments": "这是文献综合，不是作者对模型进行的新实验。94 篇中，48 篇（51.1%）研究多个漏洞类别，81 篇（86.2%）采用多种红队方法；相比之下，仅 38 篇报告多种缓解策略，15 篇未报告缓解策略。可分类评价方式的 69 篇中，61 篇（88.4%）仅使用自动或算法评价，25 篇未报告可分类的评估者类型（第 12—15 页）。综述据此指出，攻击发现的覆盖面扩展快于分层防御的证据积累；指标必须连同模型版本、任务、威胁模型、攻击强度、正常效用与评判方式解读，不能将异质结果直接平均或排名。",
    "contribution": "论文以跨层攻击面分类连接攻击机制与应用场景，并归纳提示加固、过滤、对抗训练、检索增强、交叉模型核验及领域安全层等防御家族；同时提出统一报告要素和持续红队、分层防御的研究建议。覆盖边界受检索方案影响：未报告前向引文追溯及若干主要安全会议的独立筛查，也未以专门检索词系统覆盖数据投毒、后门和模型窃取。因此，相关主题在语料中的数量不能解释为现实发生率或严重程度；这些结论反映的是本次综述的收录与编码设计。\n---\nDOI: 10.1007/s10207-026-01339-6",
