    "experiments": "在信用风险、收入预测和教育等领域的五个公开表格数据集上，方法相较原 CACTUS 改善情境对齐与因果一致性指标，同时在有效性、邻近度和稀疏性方面保持竞争力。消融揭示有效性与情境约束之间存在权衡，不能把单一指标提升理解为各项性能同时最优。",
    "contribution": "贡献是把自动发现的因果结构与情境约束联合纳入潜在空间反事实搜索。若学到的图漏边、或潜在空间重建失真，建议仍可能不可靠；论文证据集中于表格数据，图像和时间序列上的适用性需另行验证。\n---\nDOI: 10.1007/s10994-026-07155-2",
