    "method": "增量算法按节点顺序插入，每个新节点与已插入节点中最近的 k 个相连。论文用归纳法证明任意 k 下图均连通，并讨论节点排序对结构的影响；随后在 SentenceTransformer 嵌入上以 Laplacian eigenmaps 进行文本聚类，并与标准 k-NN 和 MST 修补方案对照。",
