    "contribution": "- 给出无需全局修补即可保证连通的增量 k-NN 图，并提供理论证明。\n- 在文本谱聚类中验证低 k 下的性能和内存/时间优势。\n- 局限：图的具体边仍受插入顺序影响；结论主要来自文本嵌入聚类，向其他模态、动态图与不同近邻检索近似器的扩展仍需检验。\n---\nDOI: 10.1007/s10994-026-07158-z",
