    "summary": "CALM 以 CLIP 语义正则、LoRA 和 Mixture-of-Experts 适配器实现细粒度联邦遗忘，在不重训整个全局模型的情况下移除指定客户端知识并尽量保留其余任务性能。",
    "question": "GDPR 等规则要求模型可响应“被遗忘权”，但常见联邦遗忘要么完整重训，要么粗粒度回滚参数，在非 IID 客户端下代价高、效用下降且遗忘不彻底。作者希望仅编辑与目标知识有关的参数模块，同时抑制遗忘过程导致的语义漂移。",
    "method": "框架冻结全局主干，在其上插入模块化 LoRA-MoE 适配器，借由专家路由隔离可编辑知识。CLIP 提供跨模态高层语义监督，作为正则项约束遗忘前后保留数据表示；训练目标同时考虑保留准确率、遗忘准确率、成员推断风险与通信开销。",
    "experiments": "在 CIFAR-10、CIFAR-100 和 Caltech-101 上，CALM 的保留准确率与重训相差约 2–5 个百分点。CIFAR-10/ResNet-18 客户端遗忘中，保留准确率为 66%、遗忘准确率为 3%，比重训少 4 个百分点保留精度且通信成本降低 90.8%；消融显示四个专家和中等 CLIP 权重取得较好平衡。",
    "contribution": "- 将参数高效适配、专家分工和语义正则组合为联邦遗忘的细粒度编辑机制。\n- 同时报告遗忘、效用、成员推断与通信成本，体现实际权衡。\n- 局限：专家路由在大规模异构客户端下可能不稳定；验证集中于图像分类，向文本、生成模型及更强攻击者的扩展尚待研究。\n---\nDOI: 10.1016/j.neunet.2026.109632",
