    "contribution": "- 在特定金融服务行业和地域中，对多项安全文化构念进行了联合实证检验。\n- 给出以知识、态度与规范为重点的组织安全文化干预线索。\n- 局限：样本来自四家企业且采用横截面自报问卷，不能直接推断因果；结论向其他国家、行业或组织规模推广时需复验。\n---\nDOI: 10.1007/s10207-025-01134-9",
