    "summary": "CoManTrack 面向可见光—热红外目标跟踪，通过冲突感知的空间净化与测试时流形自适应，抑制受污染模态对共享表示和长期记忆造成的级联误差。",
    "question": "RGBT 融合在暗光和遮挡下具互补性，但强热源干扰或单一模态退化会污染共享特征，并在在线更新时不断写入错误记忆。对称融合和普通记忆队列难以区分主动热干扰与被动视觉退化，容易产生轨迹漂移。",
    "method": "空间模块 CD3 根据语义分歧定向压制高能热噪声，保护脆弱的可见光结构；TSFE 用归一化极值统计补足多粒度细节。时间模块 TOMA 依据分布新颖度筛除冗余历史状态，保持紧凑而多样的目标流形，以支持稳定的测试时适应。",
    "experiments": "模型在 LasHeR、RGBT234 和 GTOT 上评测，并采用 Precision Rate、Success Rate 和 NPR。GTOT 上 CoManTrack 的 PR 为 92.6%，在表列方法中最高，SR 为 76.9%；作者还分析遮挡、光照变化、热交叉等七类挑战属性，显示其在严重跨模态退化下保持较均衡表现。",
