    "summary": "本文用 Carleman 嵌入把非线性系统提升为双线性系统，再以状态相关 Riccati 方程和三阶段同伦策略迭代，从有限状态—输入数据中学习自适应最优控制而不要求预先给出可行初始控制。",
    "question": "连续时间非线性最优控制通常需要求解难以解析处理的 HJB 方程；策略迭代方法还常要求一个一开始就稳定且可行的控制策略，而在系统动力学未知或系统本身不稳定时，这个初始控制并不容易获得。已有线性化方法通常只在工作点附近有效，或需要部分模型知识。作者希望扩大近似范围，并通过数据直接学习控制器，同时降低初始化和多组未知函数逼近带来的计算负担。",
    "method": "对于可用有限多项式表示的非线性系统，作者用 Carleman 嵌入把状态提升到包含高阶单项式的空间，得到双线性系统。对应的最优反馈控制通过状态相关 Riccati 方程求取，从而绕开直接求解 HJB。随后提出三阶段同伦策略迭代：第一阶段从数据学习辅助参数，第二阶段逐步构造使提升系统稳定的初始矩阵，第三阶段迭代学习最优控制相关参数。算法只使用状态和输入测量，自动更新初始参数，并让同一组神经网络基函数逼近所需未知函数；提升阶数可以调节精度与计算规模的折中。",
    "experiments": "论文给出两个仿真案例，并与对应 HJB 最优解比较。标量系统为 ż = -0.1z + zu，代价为 ∫(z²+u²)dt；Carleman 截断阶数从 2、4 增大到 6 时，闭环响应和控制信号逐渐接近 HJB 解，稳定区域也随之扩大。在不稳定的 Van der Pol 振荡器案例中，采用二阶截断时，第一阶段在 1 次迭代后得到参数 β，第二阶段在 14 次迭代后获得稳定矩阵，第三阶段在 13 次迭代后收敛；比较截断阶数 1、2、3 的闭环轨迹、稳定边界和代价可见，阶数增加会使控制代价逐渐接近 HJB 结果，三阶时已经非常接近全局最优参考。",
    "contribution": "论文将 Carleman 提升、状态相关 Riccati 方程和三阶段无模型策略迭代结合起来，缓解了可行初始策略和已知输入动力学的要求，并用两个案例展示截断阶数对稳定域和最优性的影响。关键局限是理论收敛与稳定性分析主要针对可有限多项式表示的系统；一般非线性系统的 Taylor 展开包含无限项，有限截断会引入并传播未建模误差，因此现有结论不能直接推广。实验也仅为仿真，尚未覆盖噪声、在线数据不足、计算资源限制和真实工程系统中的模型失配。\n---\nDOI: 10.1016/j.neunet.2026.109611",
