    "summary": "研究提出由 RLCC 引擎驱动的农业网络安全框架，在感知、网络、边缘和云/应用层之间协调预防、检测、缓解与审计行动。",
    "question": "农业 4.0 依赖传感器、自治农机、云端管理与数据驱动决策，也使设备、供应链系统和农业数据暴露于网络攻击。现有防护常按基础设施层分散部署，难以在事件发生时形成跨层协调响应。",
