    "contribution": "贡献是把农业网络安全挑战系统映射到多层架构，并用形式化协调算法连接感知与响应。局限是成果主要是概念框架和原型规划，尚缺真实农场中的攻击实验、性能开销、误报率及跨组织治理验证。\n---\nDOI: 10.1007/s10207-026-01327-w",
