    "summary": "论文提出二元分类的方程发现方法 EDC，通过搜索并拟合简洁的符号表达式，直接给出可读的分类决策边界；表达式经 logistic 映射产生分数，其阈值决定类别。（PDF页1–3）",
    "question": "符号方程发现长期偏重数值回归；分类任务虽已有遗传编程等符号方法，却常难兼顾准确率、表达简洁度和可解释性。随机森林、神经网络等分类器表现强，但难以直接向领域人员展示边界由哪些特征关系构成。作者因此聚焦二元分类，希望在保留单一、可检查方程的同时，覆盖非线性边界；多分类不在本文直接研究范围内。（PDF页2–5）",
    "method": "EDC 用可配置的上下文无关语法限定候选式，通用语法以加和项组合线性项、特征交互/二次项及幂项，并尽量删去语义重复的结构；领域专家也可增删构件。算法逐层添加项，以 beam search 保留较有希望的候选；对各式常数，专用 hill climber 先随机采样起点，再沿参数坐标试探步进，以 logistic 后的 log loss 为优化目标。模型分数用 AUC 评估，分类阈值按等误分类代价下的准确率选择。（PDF页5–8）",
    "experiments": "人工实验包括已知方程生成的数据（噪声从0到8、步长0.5，共1700组）和由6个高斯簇构成的100组数据；在后者，EDC平均AUC为0.965，低于MLP的0.972、SVM的0.970和随机森林的0.967，但优于所比较的符号分类与其他可解释基线。UCI的9个真实二元数据集采用10折交叉验证，EDC平均AUC为0.869、平均排名3.56；低于MLP和随机森林的0.898及SVM的0.894，高于全部符号方程分类基线和决策树。临界距离分析未显示主流方法相对EDC有显著优势。简化语法在这些数据上的平均AUC由0.869降至0.851，作者报告其运行可快约40–50倍；这些结果限于所测数据和配置。（PDF页10–18）",
    "contribution": "贡献是把符号方程搜索系统化用于分类边界，并以人工已知机制、簇数据和UCI基准检验其表达能力与性能—计算折衷。局限包括搜索受语法和深度约束（标准设置至多涉及12个特征），交互项会显著增加计算量；在IONOSPHERE、SONAR等数据上黑盒模型得分更高，提示当前构件可能漏掉关键关系。噪声实验中EDC超过原生成方程的AUC，反映加噪后有效边界可偏移，不能解读为恢复了唯一“真方程”；不同表达式也可能形成近似边界。（PDF页15–19）\n---\nDOI: 10.1007/s10994-026-07156-1",
