    "summary": "作者提出 NucleicBERT，以大量未标注 ncRNA 序列进行掩码语言建模，再将单序列表征用于 RNA 结构与功能预测；结果显示它能提取部分结构相关信号，并在若干指定基准上达到或超过已有方法。（PDF 第 1–2、4–6 页）",
    "question": "RNA 序列远多于有实验结构标注的数据，许多传统预测方法还依赖计算昂贵或深度不足的多序列比对（MSA）。作者要检验：不输入进化比对、只从单条序列自监督预训练，能否学到可迁移的序列规律，以及这些表征是否与已知结构约束相关。（PDF 第 1–2 页）",
    "method": "模型为 32 层、404M 参数的 BERT 类 Transformer，在 MARS 中约 3,000 万条 ncRNA 序列上训练，以掩码核苷酸预测学习上下文表征；验证集掩码预测准确率为 83.1%。（PDF 第 2、10 页）下游任务通过微调或冻结骨干网络训练任务头，涵盖二级结构、三维距离/接触图、剪接位点和 CPEB3 核酶突变体活性。作者还用 saliency、attention、序列打乱扰动及 PHATE/kNN 分析表征；MLI 耦合信号逐序列计算、不使用 MSA，之后才按家族汇总与 MSA 方法比较。（PDF 第 4–13 页）",
    "experiments": "在二级结构预测中，ArchiveII600 的 F1 为 0.872，略低于 RNAErnie+ 的 0.875；TS0 上为 0.649，高于表列基线。（PDF 第 4–6 页）长程接触图（间隔至少 24 个残基）Top-L precision 为 0.460，高于 RiNALMo 的 0.389；四物种剪接位点平均准确率为 0.948，高于 RiNALMo 的 0.945。（PDF 第 4、6 页）CPEB3 活性预测在完整微调下的测试集 R² 为 0.994，随机初始化为 0.914、近邻基线为 0.669，但 RNA-FM 为 0.996；冻结骨干后仅训练回归头，各模型 R² 均不大于 0。这是单一核酶突变数据集上的测量标签预测，不能外推为普遍功能预测能力。（PDF 第 6–7、13 页）打乱实验中，真实性分类准确率与打乱比例相关（r = −0.951）；14 个 Rfam 家族的 MLI 信号高于随机基线、低于依赖 MSA 的 MI/DCA。（PDF 第 7–9 页）",
    "contribution": "工作将单序列预训练用于多种 RNA 任务，并以冻结表征对照、扰动和可解释性分析区分预训练信号与任务微调效果；结果支持模型表征与结构/进化约束相关，但相关性本身不证明模型学得了因果机制。（PDF 第 2、6–10 页）评估范围仍受标注结构稀缺、所选基准与单一 CPEB3 功能数据限制；论文说明下游基准为固定测试集单次评估、未报告重复标准误，因此优势的跨数据集稳定性仍待独立验证。（PDF 第 4、6、11、13 页）PDF 首页“Published online”日期仍是占位符，故保留原总结中已核实的 2026-09-03；仅凭该 PDF 无法确认其具体在线发表版本日期。（PDF 第 1 页）\n---\nDOI: 10.1038/s42256-026-01295-9",
