    "summary": "提出推理模型内隐关联测验（RM-IAT）研究推理模型中的类隐式偏见处理：通过逐步推理完成任务的模型对「与刻板印象不一致」的关联任务消耗显著更多的推理 token，表明其存在类隐式偏见模式。",
