    "direction": "信息安全",
    "summary": "MSTE-CAN 将 CAN 总线报文编码为多通道时空图像，再用浅层坐标注意力增强的 ResNet-18 检测入侵，在公开数据集上兼顾细粒度攻击表征与低推理延迟。",
    "question": "CAN 总线原有协议缺少发送者认证、加密和完整性保护，恶意流量可以通过报文注入干扰车辆功能。车载检测既要识别细微伪造，又要控制资源消耗与延迟；只观察一维报文序列，可能掩盖空间状态、时间变化和统计偏移之间互补的攻击特征。本文尝试把这些特征显式编码，再以轻量视觉网络进行识别。",
    "method": "按时间顺序先划分数据，再在各分区内部构造互不跨界的报文窗口，以降低相邻窗口造成的数据泄漏风险。MSTE 把空间信号状态、时间差分与统计偏移分别编码到三个通道；默认 27 条报文形成 27×9×3 张量，经最近邻插值放大到 224×224 图像，以保留离散字段边界。ResNet-18 仅在最浅层配置坐标注意力，突出与报文字节位置对应的异常特征，避免在深层重复加入注意力带来的额外开销。",
    "experiments": "在 Car-Hacking-Dataset 上，准确率为 99.96%，宏平均 F1 为 0.9989，误报率和漏报率分别为 0.0295% 与 0.0631%。ROAD 的 95.85% 准确率、0.7928 宏平均 F1 来自保持相同架构和超参数的独立重新训练，不能当作源模型零样本迁移成绩。真正从 Car-Hacking 迁移到 HCRL 的实验使用目标训练分区拟合归一化参数，获得二分类 F1 0.9328，但仍有正常流量域偏移导致的误报。论文报告约 1.1341 毫秒推理时间，实验环境为 GPU 工作站，而非量产车载 ECU；消融支持浅层注意力与三个编码通道的作用。",
    "contribution": "- 贡献：将互补的 CAN 报文特征编码为可解释的视觉表示，并以浅层坐标注意力在精度和计算量之间取得较好折中；同时区分同域训练、独立跨平台训练与跨数据集迁移，分析性能差异来源。\n- 局限：物理层攻击和平台特有正常流量仍会影响泛化，目标域数据与归一化方式是迁移结果的重要条件。论文将生产级嵌入式硬件上的完整流程实测、无监督或少样本域适应、传感器融合及 CAN FD 等协议扩展列为后续工作，因此不能把工作站低延迟直接等同于已完成量产车载实时部署。\n---\nDOI: 10.1016/j.cose.2026.105133",
